(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["coding"]||{};var a=d["algorithms"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="alg-speculative-draft-verify"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-draft-verify-sec-1\">一 · 事故现场：一个不该发生的尾延迟尖峰</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-draft-verify-sec-2\">二 · 它精确解决的那一类问题</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-draft-verify-sec-3\">三 · 它明确不解决的问题</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-draft-verify-sec-4\">四 · 一次失败案例的机理拆解</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-draft-verify-sec-5\">五 · 适用性判据与部署前置条件</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-draft-verify-sec-6\">六 · 边界之外：什么时候该换算法而不是调参</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-draft-verify-sec-7\">七 · 什么时候它救不了你：低接受率、KV 回滚与显存挤压的三重失效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-draft-verify-sec-8\">八 · 草稿段：γ 次自回归与 q 的产出</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-draft-verify-sec-9\">九 · 验证前向：γ 个位置合并为一次目标前向</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-draft-verify-sec-10\">十 · 接受判定与残差修正：逐位置的 min(1, p/q)</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-draft-verify-sec-11\">十一 · KV 提交与回滚：k 个 token 一次性落账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-draft-verify-sec-12\">十二 · γ 的动态调整：把 cγ 压在拐点之下</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-draft-verify-sec-13\">十三 · 验证前向的 KV 写入、回滚与容量挤压</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-draft-verify-sec-14\">十四 · 接受长度期望的逐项拆解</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-draft-verify-sec-15\">十五 · 残差分布的构造与一次性提交</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-draft-verify-sec-16\">十六 · 并行验证的算术强度账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-draft-verify-sec-17\">十七 · γ 的动态调整与负载配比</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-draft-verify-sec-18\">十八 · 可实现性边界与工程判断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-draft-verify-sec-19\">十九 · 接受长度期望的推导边界与回滚代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-draft-verify-sec-20\">二十 · 请求形态的匹配：短 prompt、中等生成长度、高并发小批</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-draft-verify-sec-21\">二十一 · 并发与批大小的耦合：γ 挤占的是位置预算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-draft-verify-sec-22\">二十二 · 接受率的负载依赖性：任务分布决定 γ 的最优点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-draft-verify-sec-23\">二十三 · 显存与并发的挤压：草稿模型同驻的容量账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-draft-verify-sec-24\">二十四 · 负载不对时的三种退化形态与判别信号</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-draft-verify-sec-25\">二十五 · 配方落点：把 γ 与路由做成调度层决策</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-draft-verify-sec-26\">二十六 · 负载配方：短提示、中等生成、高并发小批才是它的主场</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-draft-verify-sec-27\">二十七 · 硬件档位：把草稿与目标的驻留预算一起算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-draft-verify-sec-28\">二十八 · 并行拓扑：验证前向的切分方式决定通信代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-draft-verify-sec-29\">二十九 · 量化方案：草稿与目标的精度不必对齐</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-draft-verify-sec-30\">三十 · KV 策略：提交、回滚与一致性</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-draft-verify-sec-31\">三十一 · 调度参数：γ 的闭环控制与批的耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-draft-verify-sec-32\">三十二 · 配方边界：草稿与目标同驻时的显存账、γ 的失效区间与 KV 回滚代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-draft-verify-sec-33\">三十三 · 显存占用：草稿权重与 KV 的双重挤压</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-draft-verify-sec-34\">三十四 · 带宽：验证前向的算术强度红利与草稿的带宽税</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-draft-verify-sec-35\">三十五 · 通信：并行验证在张量并行与分离式部署下的放大</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-draft-verify-sec-36\">三十六 · 功耗与热：验证前向的功率尖峰</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-draft-verify-sec-37\">三十七 · 尾延迟：接受率分布的长尾与回滚成本</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-draft-verify-sec-38\">三十八 · 规模上去以后哪里先崩</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-draft-verify-sec-39\">三十九 · 接受率塌陷：从分布失配到负收益</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-draft-verify-sec-40\">四十 · 验证前向的 KV 回滚与显存越界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-draft-verify-sec-41\">四十一 · 批抖动：γ 动态调整与连续批处理的耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-draft-verify-sec-42\">四十二 · 路由不均与尾延迟尖刺</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-draft-verify-sec-43\">四十三 · 监控指标与回滚开关</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-draft-verify-sec-44\">四十四 · 失效边界：从接受率塌陷到 KV 回滚的工程诊断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-draft-verify-sec-45\">四十五 · 同族谱系与选型维度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-draft-verify-sec-46\">四十六 · 决策表：五类候选的适用条件</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-draft-verify-sec-47\">四十七 · 选型伪代码：按接受率与显存余量分流</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-draft-verify-sec-48\">四十八 · 与调度层和量化手段的叠加次序</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-draft-verify-sec-49\">四十九 · 失败模式归因与切换判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-draft-verify-sec-50\">五十 · 同族算法选型：草稿-验证的边界与替代路径</button></li></ol></nav><figure class=\"diagram\" data-fig=\"algo-flow\"><svg style=\"max-width:574px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 573.8 352\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"491.8\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">草稿模型基于当前上下文自回归生成 γ 个候选 token 及其概率 q。</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"491.8\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">目标模型对上下文加 γ 个候选做一次并行前向，得到每个位置的目标概率 p。</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"491.8\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">逐位置以 min(1, p/q) 接受，首次拒绝处从残差分布采样一个修正 …</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"491.8\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">接受前缀长度 k 个 token 一次性提交到 KV cache，解码位置…</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"491.8\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">根据接受率动态调整 γ，使草稿开销与目标验证开销比值接近最优。</text></svg><figcaption><b>执行流程</b> · 从输入到输出的关键步骤；每一步的复杂度与坑在正文展开。</figcaption></figure>\n<h3 id=\"alg-speculative-draft-verify-sec-1\">一 · 事故现场：一个不该发生的尾延迟尖峰</h3>\n<p>某代码补全服务在灰度扩量后出现一类难以复现的故障：平均每 token 时延仍在 SLO 之内，但 P99 尾延迟成倍抬升，客户端表现为编辑器里补全候选“卡住半秒才弹出”。排查排除了网络与调度队列，问题落在解码循环本身。该服务当时采用纯自回归解码，batch 内并发请求数被压得很小以保住单请求时延，于是每一步前向只处理极少 token，权重读取的内存带宽开销被摊薄得极差——SM 上的 tensor core 大量空转，GPU 处于典型的 memory-bound 状态。更麻烦的是 agent 循环场景：一次工具调用前后的上下文拼接使序列变长，逐 token 串行解码把“每步一次完整权重扫描”的成本乘以生成长度，尾延迟随上下文线性恶化。这个事故说明的不是“模型太慢”，而是解码的数据流形态与硬件能力错配：算力闲置、带宽打满、串行依赖无法用增大 batch 之外的手段掩盖。</p>\n<p>投机草稿-并行验证正是针对这一形态的算法级修正。它不改变目标模型，不改变采样语义，只改变“一次前向产出多少 token”这件事：用廉价草稿模型一次提出 γ 个候选，目标模型用一次并行前向对这 γ 个位置同时打分，再按接受规则提交最长一致前缀。事故中的尾延迟尖峰，本质是每 token 一次前向的固定带宽成本无法被算术强度摊薄；把 γ 个位置合并进一次前向，等于把这次前向的算术强度抬高 γ 倍量级，而权重读取次数不变。</p>\n\n<h3 id=\"alg-speculative-draft-verify-sec-2\">二 · 它精确解决的那一类问题</h3>\n<p>适用边界的第一条是负载形态：短 prompt、中等生成长度、高并发小批，SLO 以每 token 时延与尾延迟为目标。代码补全与 agent 循环正好落在这个区间——请求短、生成中等、并发高，但单请求又必须快。第二条是瓶颈位置：单步解码受内存带宽限制而非算力限制。若某负载已经是 compute-bound（例如极大的 batch 或极长的 prefill 主导），并行验证带来的算术强度收益会被稀释，加速比趋近于 1 而草稿开销照付。第三条是正确性敏感度：接受判定保证输出分布与目标模型严格一致，这使得该算法可以安全地用于结构化输出与工具调用——这两类场景一旦分布偏移，就会产生语法合法但语义错误的调用参数，事后无法用重试修复。</p>\n<p>加速比的上界由接受长度与草稿成本共同决定：</p>\n<div class=\"formula\">$$\\mathbb{E}[\\text{接受长度}]=\\sum_{i=1}^{\\gamma}\\prod_{j=1}^{i}\\min\\left(1,\\frac{p_j}{q_j}\\right),\\quad \\text{加速比}\\approx\\frac{\\mathbb{E}[\\text{接受长度}]+1}{1+c\\gamma}$$</div>\n<p>其中 c 是草稿单步成本相对目标单步成本的比例。这个式子给出两个工程判断：其一，γ 不是越大越好，分母随 γ 线性增长而分子受连乘衰减约束，存在一个由接受率决定的最优 γ；其二，若草稿模型不够廉价（c 接近或超过 1），即使接受率很高也可能负收益。事故服务若盲目把 γ 拉到 8 而不看接受率，草稿开销会直接吃掉验证收益，尾延迟反而更差。</p>\n\n<h3 id=\"alg-speculative-draft-verify-sec-3\">三 · 它明确不解决的问题</h3>\n<p>第一，它不解决 prefill 阶段的长上下文计算问题。并行验证只作用于 decode 的逐 token 串行段，prefill 的算力开销、注意力复杂度、KV 写入量都不在它的作用域内；把长上下文首 token 时延归因于解码串行是误诊。第二，它不解决显存容量问题，反而加剧：草稿模型额外占用显存与算力，与目标模型同驻时挤压并发批大小，低延迟 SLO 下的容量规划必须把两份权重与两份 KV 同时计入。第三，它不改变调度层的重叠关系。与投机检索预取的区别正在此处——后者在调度层重叠检索与生成、不改解码分布；本算法改的是解码数据流本身，分布严格不变。第四，它不解决 KV 缓存的分页与复用问题，那是分页 KV 块管理与基数树前缀缓存复用的主题；本算法只额外引入验证前向的 KV 写入与回滚需求。</p>\n<p>边界还要说清规模上限：受草稿显存与接受率约束，具体数字未给出，但定性上，当并发批已经大到目标模型进入 compute-bound 区间，或当任务本身接受率极低（草稿与目标分布差异大，如跨语言、跨风格迁移），该算法的净收益会退化甚至为负。此时正确的动作是缩 γ 或换草稿，而不是加机器。</p>\n\n<h3 id=\"alg-speculative-draft-verify-sec-4\">四 · 一次失败案例的机理拆解</h3>\n<p>把事故复盘成机理：某 agent 循环在工具返回后拼接长上下文，草稿模型基于当前上下文自回归生成 γ 个候选及其概率 q；目标模型对上下文加 γ 个候选做一次并行前向，得到每个位置的目标概率 p。逐位置以 $$\\min\\left(1, \\frac{p}{q}\\right)$$ 接受，首次拒绝处从残差分布采样一个修正 token 并截断后续候选，残差分布为 $$\\max(0,\\ p - q)$$ 归一化后的分布。接受前缀长度 k 个 token 一次性提交到 KV cache，解码位置前进 k+1，未接受候选丢弃。</p>\n<p>失败点在两处。其一是接受率：工具调用场景下草稿模型对结构化参数（JSON 键名、枚举值）的先验弱，q 与 p 偏离大，接受长度期望被连乘迅速压低，γ 个候选里常常只接受 1 个，加速比趋近于 1 而草稿成本照付。其二是 KV 一致性：验证前向对 γ 个位置都写了 KV，但只有前 k 个被提交，剩余 γ−k 个必须回滚；长上下文下草稿与目标 KV 的一致性维护复杂，回滚若用朴素拷贝会引入额外带宽开销，恰好抵消并行验证省下的带宽。这两点共同解释了尾延迟尖峰——不是平均变慢，而是长上下文请求在低接受率下反复触发“验证—回滚—重来”的循环。</p>\n<p>工程上的处置是按接受率动态调 γ，使草稿开销与目标验证开销比值接近最优；同时把 KV 回滚做成块级元数据操作而非数据拷贝，避免在长上下文下把省下的带宽又还回去。稳定性技巧的核心就是这条反馈环：接受率是观测量，γ 是控制量，c 是硬件与模型给定的常数。</p>\n\n<h3 id=\"alg-speculative-draft-verify-sec-5\">五 · 适用性判据与部署前置条件</h3>\n<p>给出可执行的判据，而不是笼统的“看情况”。判据一：测量目标模型单步解码的算术强度，若远低于硬件峰值且随 batch 增大改善有限，说明处于 memory-bound，适用。判据二：离线或在线统计草稿对目标的接受率，若期望接受长度显著大于 1 且 cγ 项可控，适用；若接受长度接近 1，先修草稿再谈 γ。判据三：显存预算能否同时容纳草稿与目标权重及其 KV，且不把并发批压到破坏 SLO 的程度。判据四：正确性要求是否允许分布偏移——不允许时本算法是少数几个能给出严格一致保证的加速手段，这一点在结构化输出与工具调用上是硬需求。</p>\n<table class=\"mini\"><thead><tr><th>判据</th><th>适用信号</th><th>不适用信号</th><th>系统代价落点</th></tr></thead><tbody><tr><td>瓶颈位置</td><td>单步解码 memory-bound，算力闲置</td><td>已进入 compute-bound</td><td>带宽、算力利用率</td></tr><tr><td>接受率</td><td>期望接受长度明显大于 1</td><td>接受长度趋近 1</td><td>草稿算力、尾延迟</td></tr><tr><td>显存</td><td>可同驻两份权重与 KV</td><td>挤压并发批至 SLO 失守</td><td>显存容量、并发度</td></tr><tr><td>正确性</td><td>需分布严格一致</td><td>可容忍分布偏移</td><td>采样语义、工具调用正确率</td></tr></tbody></table>\n<p>前置条件还包括 KV 管理能力：验证前向的写入与回滚必须与分页 KV 块管理协同，否则长上下文下草稿与目标 KV 一致性维护会变成主要成本项。硬件档位需同时容纳草稿与目标权重及其 KV，这是容量规划里最容易被漏算的一项——事故服务扩容时只按目标模型算显存，草稿一上线就把 batch 上限打了下来，尾延迟因此恶化。</p>\n\n<h3 id=\"alg-speculative-draft-verify-sec-6\">六 · 边界之外：什么时候该换算法而不是调参</h3>\n<p>当负载已经从 memory-bound 迁移到 compute-bound，调 γ 无济于事，因为并行验证的收益来源就是算术强度的提升，而算力已被占满；此时应转向批调度与连续批处理层面的优化。当正确性要求允许近似，且草稿质量极差，可以考虑特征级投机或多解码头投机这类不依赖独立草稿模型的路线，但它们与本算法在分布保证上的取舍不同。当瓶颈在检索与生成的调度重叠而非解码串行，投机检索预取才是对的工具——它不改解码分布，也不承担草稿显存。反过来，当结构化输出与工具调用要求分布严格一致，且解码确实受带宽限制，本算法是少数同时满足“加速”与“不变分布”两个约束的选项，代价是显存与 KV 回滚复杂度，这两项必须在容量规划阶段就计入，而不是上线后被动扩容。</p>\n\n<h3 id=\"alg-speculative-draft-verify-sec-7\">七 · 什么时候它救不了你：低接受率、KV 回滚与显存挤压的三重失效</h3>\n<p>先用一个线上事故把边界钉死。某代码补全服务在灰度中把草稿模型与目标模型同驻一张卡，压测时 p99 每 token 时延反而高于纯自回归基线，且尾延迟抖动放大。根因不是草稿模型太慢，而是该批请求的上下文来自一段高度风格化的生成代码，草稿模型对目标分布的拟合极差，逐位置接受概率长期偏低，γ 个候选里通常只有第一个被接受。此时草稿的 γ 次串行前向全部白做，验证前向虽把 γ 个位置合并成一次、算术强度提高，但摊到每个被接受的 token 上的有效算力反而上升；同时验证阶段的 KV 写入与回滚在长上下文下要维护草稿与目标两份 KV 的一致性，回滚路径上的额外缓存管理把尾延迟进一步推高。这就是“加速比退化甚至负收益”的典型形态：算法本身没错，错在把它用在了接受率不成立的任务上。</p>\n<p>把失效条件写成可判定的量。设草稿单 token 开销相对目标单 token 开销为 c，草稿长度 γ，则</p>\n<div class=\"formula\">$$\\mathbb{E}[\\text{接受长度}]=\\sum_{i=1}^{\\gamma}\\prod_{j=1}^{i}\\min\\left(1,\\frac{p_j}{q_j}\\right),\\quad \\text{加速比}\\approx\\frac{\\mathbb{E}[\\text{接受长度}]+1}{1+c\\gamma}$$</div>\n<p>分母里的 cγ 是草稿的固定税，分子是验证换来的产出。当逐位置接受概率乘积快速衰减时，E[接受长度] 趋近于 1 附近，加速比趋近 2/(1+cγ)；只要 cγ 足够大，这个比值就掉到 1 以下。工程判断因此很直接：γ 不是越大越好，它必须与实测接受率联动，按接受率动态调 γ 使草稿开销与验证开销比值接近最优，是这套方案能否成立的前提而非可选优化。低接受率任务上正确的动作是缩 γ 甚至退回纯自回归，而不是硬扛。</p>\n<table class=\"mini\"><thead><tr><th>边界维度</th><th>成立条件</th><th>失效表现</th></tr></thead><tbody><tr><td>任务分布</td><td>草稿与目标分布接近，接受率高</td><td>风格化/罕见上下文，接受长度趋近 1，负收益</td></tr><tr><td>上下文长度</td><td>KV 回滚代价可控</td><td>长上下文下双份 KV 一致性维护复杂，尾延迟抬升</td></tr><tr><td>显存预算</td><td>草稿与目标权重及 KV 同驻有余量</td><td>挤压并发批大小，低延迟 SLO 下容量受限</td></tr></tbody></table>\n<p>它明确不解决的问题也要说清：它不改变解码分布，因此对“目标模型本身就错”的正确答案问题无能为力；它不解决调度层的检索与生成重叠，那是投机检索预取的角度，两者常被混谈但边界不同；它也不适用于算力受限而非带宽受限的场景——验证前向合并 γ 个位置提升算术强度的收益，恰恰来自原先逐 token 解码被内存带宽卡住、算力闲置，若负载已是计算密集，合并带来的边际收益迅速消失。规模上限受草稿显存与接受率共同约束，具体数字未给出，但判断顺序固定：先测接受率分布，再定 γ 与是否同驻，最后才谈加速。</p>\n<h3 id=\"alg-speculative-draft-verify-sec-8\">八 · 草稿段：γ 次自回归与 q 的产出</h3>\n<p>验证-接受循环的起点不是目标模型，而是草稿模型对当前解码位置的连续 γ 次前向。输入是截至位置 t 的上下文（prompt 加已提交 token）以及目标模型侧的 KV 视图；输出是 γ 个候选 token $x_{t+1},\\dots,x_{t+\\gamma}$ 与每个位置上的草稿概率 $q_j(\\cdot)$。注意这里的 q 不是单个标量，而是该位置上草稿模型对整个词表的分布——接受判定需要逐 token 取 $q_j(x_j)$，残差采样需要完整的 $q$ 向量，因此草稿段必须把 γ 个位置的分布留存下来，而不能只留 argmax 的 token id。</p>\n<p>代价结构上，草稿段是纯串行的 γ 步解码，每步都要读一遍草稿权重与草稿 KV，属于典型的带宽受限小算子。它的绝对时延正比于 γ，但单步成本远低于目标模型，因为草稿模型参数量小、层数浅。工程上真正要盯的是比值 $c=\\text{草稿单步代价}/\\text{目标验证前向代价}$：γ 增大时草稿段线性变贵，而验证段因为把 γ 个位置合并成一次前向，边际成本增长远慢于线性。草稿段还有一个隐性代价——它必须与目标模型共享同一份上下文语义，若两者 tokenizer 或位置编码约定不一致，q 与 p 就不可比，接受率会无声塌陷。</p>\n<p>具体例子：代码补全场景中，草稿模型在补全一个函数体时连续吐出 γ=4 个候选，其中前两个是缩进与常见变量名，后两个开始发散。此时草稿段付出的 4 步串行时延，换来的是一次目标前向覆盖 4 个位置的机会；若后两个候选明显偏离，接受长度会停在 2，草稿段后两步的算力即为沉没成本。</p>\n\n<h3 id=\"alg-speculative-draft-verify-sec-9\">九 · 验证前向：γ 个位置合并为一次目标前向</h3>\n<p>验证段把「上下文 + γ 个候选」拼成一条长度 $t+\\gamma$ 的序列，送进目标模型做一次因果前向。由于因果掩码，位置 $t+j$ 的输出只依赖到 $t+j$ 为止的 token，恰好就是「若前 j−1 个候选全被接受」条件下目标模型对第 j 个位置的预测。这一次前向同时产出 γ 组目标分布 $p_1,\\dots,p_\\gamma$，把原本需要 γ 次串行目标前向的工作压成一次。</p>\n<p>这一步是整条流水线算术强度最高的环节：batch 维没有变大，但序列维被拉长了 γ，矩阵乘的规模随之上升，权重读取被摊薄到更多 token 上，每 token 的有效内存带宽压力下降。代价则转移到了注意力的 KV 上——验证前向会为这 γ 个位置写入 KV，而这些位置尚未被接受，属于「临时 KV」。以 GQA/MQA 的 Blackwell 实现为例，验证前向的 KV 写入量与 γ 成正比，长上下文时这部分写入在总带宽中占比不可忽略；同时验证前向的 logits 张量形状是 $\\gamma\\times V$，词表大时这块中间结果的显存占用与写出带宽都要计入。</p>\n<div class=\"formula\">$$\\mathbb{E}[\\text{接受长度}]=\\sum_{i=1}^{\\gamma}\\prod_{j=1}^{i}\\min\\left(1,\\frac{p_j}{q_j}\\right),\\quad \\text{加速比}\\approx\\frac{\\mathbb{E}[\\text{接受长度}]+1}{1+c\\gamma}$$</div>\n<p>上式给出验证段的设计约束：加速比的分母里 $c\\gamma$ 就是草稿段相对验证段的相对开销。当 c 固定，γ 存在一个由接受率曲线决定的最优点；接受率随 γ 衰减越快，越应该把 γ 压小。工程判断是：不要按「γ 越大越好」调参，而应按实测的逐位置接受概率曲线找拐点，把 γ 设在乘积项开始陡降之前。</p>\n\n<h3 id=\"alg-speculative-draft-verify-sec-10\">十 · 接受判定与残差修正：逐位置的 min(1, p/q)</h3>\n<p>验证前向结束后，接受判定按位置顺序推进：对第 j 个位置抽一个均匀随机数 $u_j$，若 $u_j\\le\\min(1,p_j/q_j)$ 则接受该候选，否则在此处拒绝。接受判定的输入是成对的 $(p_j(x_j), q_j(x_j))$，输出是一个布尔序列；这个序列一旦出现首个 false，后续候选全部作废，不再判定。这一步的计算量极小，但它决定了整条流水线的走向，因此不能在 GPU 上做成需要同步的逐位置分支——常见做法是把 γ 个位置的判定并行算出，再用前缀与（prefix-AND）求出首个拒绝位置，避免 γ 次串行同步。</p>\n<p>首个拒绝位置的处理是分布正确性的关键：从残差分布 $\\max(0,p-q)$ 归一化后采样一个修正 token，替换掉被拒绝的候选，并截断其后所有候选。残差分布必须用完整的 p、q 向量构造，这也是为什么草稿段要留存整组分布。代价方面，残差采样是一次小规模的按词表加权采样，词表大时需要对 $V$ 维向量做归一化与累积和，属于轻量但不可省略的算子；若把它放在关键路径上串行执行，会引入一次额外的 kernel 启动与同步开销。</p>\n<p>具体例子：工具调用场景中，草稿模型给出一个 JSON 键名但概率偏低，目标模型在该位置的 p 明显高于 q，判定通过；下一个位置草稿给出一个不合语法的括号，目标模型 p 在该 token 上接近零，$\\min(1,p/q)$ 极小，判定几乎必然拒绝，于是从残差分布采出一个合法 token 并丢弃后续候选。输出分布因此与目标模型严格一致，这正是该机制能用于结构化输出的原因。</p>\n\n<h3 id=\"alg-speculative-draft-verify-sec-11\">十一 · KV 提交与回滚：k 个 token 一次性落账</h3>\n<p>设接受前缀长度为 k（含残差修正 token 时提交 k+1 个），解码位置前进 k+1。提交动作的输入是验证前向已经写入的临时 KV 与接受掩码，输出是 KV cache 中被正式确认的 k+1 个槽位。这里有两种实现路线：其一，验证前向直接把 KV 写进正式 cache 的连续槽位，接受后仅更新长度指针，拒绝时把指针回退到 k+1 处，被丢弃候选的 KV 成为垃圾等待后续覆盖；其二，验证前向写入独立的临时缓冲，接受后再拷贝进正式 cache。前者省一次拷贝但要求分页块表能容忍「写了但未提交」的槽位，后者语义干净但多一次 KV 搬运，长上下文下这次搬运的带宽开销与 k 成正比。</p>\n<p>回滚的正确性依赖块表与长度指针的原子更新：长度指针必须先于块表可见性更新，否则并发的连续批处理调度器可能读到半提交状态。在分页 KV 体系下（其块管理细节见本模块另一条目），被拒绝候选所占的块若跨越块边界，回滚需要把跨界的部分块标记为可复用，这会带来块级碎片。代价上，验证前向的 KV 写入与回滚共同构成「额外缓存管理」开销：写入量正比于 γ，回滚的元数据操作正比于被丢弃的块数，二者在长上下文、高并发小批的负载下会挤压有效批大小。</p>\n<p>具体例子：agent 循环中一次工具返回后追加了长观察文本，上下文已达数万 token，草稿提出 γ=6 个候选，验证后只接受 k=2。此时验证前向为 6 个位置写入了 KV，其中 4 个被回滚；若采用临时缓冲路线，还要把 2 个位置的 KV 拷进正式 cache。这次拷贝在长上下文下的带宽占用，可能已经接近草稿段本身的成本，因此该场景更倾向「直写正式 cache + 指针回退」的路线。</p>\n\n<h3 id=\"alg-speculative-draft-verify-sec-12\">十二 · γ 的动态调整：把 cγ 压在拐点之下</h3>\n<p>最后一步是反馈控制：用最近窗口的实测接受率估计 $\\mathbb{E}[\\text{接受长度}]$，据此调整 γ，使草稿开销与验证开销的比值接近最优。输入是滑动窗口内的接受长度统计与草稿/验证两段的实测耗时，输出是下一个请求或下一轮循环使用的 γ。控制律不必复杂：当实测接受长度接近 γ（几乎全接受）时增大 γ 以摊薄验证前向的固定开销；当接受长度显著小于 γ 时减小 γ，避免草稿段做无效串行。伪代码思路是维护一个窗口均值 $\\hat{k}$，令 $\\gamma\\leftarrow\\text{clip}(\\lceil \\hat{k}\\cdot\\alpha\\rceil,\\gamma_{\\min},\\gamma_{\\max})$，其中 α 略大于 1，使 γ 始终略高于近期接受长度，保留少量探索空间。</p>\n<p>代价与失败模式在这一步集中体现：低接受率时草稿开销超过验证收益，加速比退化甚至出现负收益；而 γ 调得过于保守，验证前向的固定开销（一次 kernel 启动、一次 logits 写出）又无法被摊薄。此外，草稿模型与目标模型同驻会额外占用显存与算力，直接压缩可用的并发批大小，在低延迟 SLO 下形成容量约束——这意味着 γ 的调整不只是性能问题，也是显存预算问题。</p>\n<p>具体例子：代码补全的短 prompt、中等生成长度、高并发小批负载下，接受率通常较高且稳定，γ 可以维持在偏大值；而 agent 循环中工具返回后的自由文本生成段接受率波动大，窗口均值会驱动 γ 快速下探，避免在发散段持续付出草稿串行时延。工程判断落在窗口长度上：窗口太短会让 γ 随单次请求抖动，窗口太长则跟不上任务段切换，通常按「一个请求内的段落切换尺度」取窗口，而不是按固定 token 数取。</p>\n\n<h3 id=\"alg-speculative-draft-verify-sec-13\">十三 · 验证前向的 KV 写入、回滚与容量挤压</h3>\n<p>并行验证那一次前向并不“免费”：目标模型要把上下文加 γ 个候选一起跑，意味着这 γ 个位置的 K/V 必须先写进目标侧 KV cache，再按接受前缀长度 k 决定保留哪一段、回滚哪一段。提交时只有前 k 个位置真正前进，解码位置跳到 k+1，其余 γ−k 个候选的 KV 条目作废。工程上这要求 KV 管理器支持“试探写入 + 截断提交”，而不是简单的追加式分配；长上下文下草稿侧与目标侧的 KV 还必须保持同一前缀视图，否则下一次草稿会基于与目标不一致的历史继续生成，接受率随之塌陷。代价是显存碎片与元数据开销：每个请求每轮都要预留 γ 个槽位，块表与引用计数需要原子地回滚，在连续批处理里这会挤占调度器的空闲块池。</p>\n<p>容量上的挤压更直接。草稿模型与目标模型同驻，权重之外还要各留一份 KV，硬件档位必须同时容纳两者；在短 prompt、中等生成长度、高并发小批的代码补全形态下，并发批大小被草稿显存直接压低，而低延迟 SLO 恰恰靠并发来摊薄单步带宽成本。于是出现一个反直觉的边界：γ 调大能提高验证阶段的算术强度、降低每 token 的内存带宽压力，但预留槽位与草稿前向的串行步数一起上升，尾延迟先恶化。加速比近似为</p>\n<div class=\"formula\">$$\\text{加速比}\\approx\\frac{\\mathbb{E}[\\text{接受长度}]+1}{1+c\\gamma}$$</div>\n<p>其中 c 是草稿单步相对目标单步的归一化代价。当接受率下滑，分子趋近 1 而分母随 γ 线性增长，比值跌破 1 即为负收益——这正是低接受率任务（如自由文本续写、跨语言改写）上必须把 γ 压到很小的原因，而代码补全与工具调用因结构强、候选集中，才撑得住较大 γ。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>触发机制</th><th>系统代价</th></tr></thead><tbody><tr><td>接受率低</td><td>草稿分布偏离目标，首次拒绝靠前</td><td>草稿算力白费，加速比 &lt; 1</td></tr><tr><td>长上下文</td><td>两侧 KV 前缀视图漂移</td><td>回滚元数据开销、显存碎片</td></tr><tr><td>高并发小批</td><td>草稿权重与 KV 挤压空闲块</td><td>批大小下降，尾延迟抬升</td></tr></tbody></table>\n<p>因此动态调 γ 不是锦上添花而是稳定器：按滑动窗口接受率把 γ 收敛到使草稿开销与验证开销比值接近最优的点，并在检测到 KV 前缀不一致时强制清空草稿侧缓存重同步。判断一个部署是否该上这套方案，看的是“每 token 是否真的被内存带宽卡住”与“草稿能否与目标共享足够长的前缀”，两者任一不成立，回滚与显存代价就会盖过并行验证带来的算术强度收益。</p>\n<h3 id=\"alg-speculative-draft-verify-sec-14\">十四 · 接受长度期望的逐项拆解</h3>\n<p>公式的第一行不是装饰，它是把“草稿质量”折算成“每轮能白拿多少 token”的唯一通道。逐项看：外层求和从 i=1 到 γ，表示“恰好接受 i 个”的贡献；内层连乘从 j=1 到 i，是前 i 个位置全部通过接受判定的联合概率。关键在于连乘里的因子 <span>min(1, p_j/q_j)</span> 不是独立事件概率的近似，而是逐位置条件接受率的精确表达——第 j 位被接受的前提是前 j−1 位已被接受，而拒绝采样在构造上让“接受第 j 位”与“前 j−1 位已接受”在概率上可乘，这正是推导的关键一步：把链式条件概率 collapse 成连乘，无需引入任何近似。</p>\n<p>为什么是 min(1, p/q) 而不是 p/q？因为当草稿概率高于目标概率（q_j &gt; p_j）时，直接按 p/q 接受会漏掉“目标比草稿更想要这个 token”的那部分质量，于是接受率封顶在 1，多出来的质量由残差分布补。这一步的代价是必须显式计算残差 max(0, p−q) 并归一化，否则分布一致性被破坏——在结构化输出与工具调用场景里，这个归一化是硬约束，不能省。</p>\n<div class=\"formula\">$$\\mathbb{E}[\\text{接受长度}]=\\sum_{i=1}^{\\gamma}\\prod_{j=1}^{i}\\min\\left(1,\\frac{p_j}{q_j}\\right),\\quad \\text{加速比}\\approx\\frac{\\mathbb{E}[\\text{接受长度}]+1}{1+c\\gamma}$$</div>\n<p>第二行把期望折算成端到端加速比。分子 E[接受长度]+1 是每轮实际推进的 token 数（接受前缀 k 个加一次修正 token，解码位置前进 k+1）；分母 1+cγ 是每轮的时间成本，其中 1 代表目标模型的一次并行前向（归一化为单位时间），cγ 是草稿模型自回归 γ 步的相对开销，c 是草稿单步相对目标单步的代价比。这个式子的工程含义很直接：γ 增大时分子趋近于 γ 的上界但增速递减（连乘逐项衰减），分母线性增长，因此存在一个由接受率曲线与 c 共同决定的最优 γ。低接受率任务上，连乘迅速塌到接近零，分子停在 1 附近而分母仍在涨，加速比小于 1 就是负收益——这正是失败模式里“低接受率退化”的数学来源，不是偶发。</p>\n<p>一个具体例子：代码补全场景中，草稿模型对缩进、括号闭合这类高置信 token 的 q 接近 1，目标模型 p 也接近 1，该位置因子≈1；而对标识符命名的分歧位置 p/q 可能只有 0.3，连乘在此处断崖。于是 E[接受长度] 由“分歧点出现的位置”主导，而非平均接受率。工程判断因此是：调 γ 不能只看全局接受率均值，要看接受长度的分布形状——尾部长尾意味着偶发的高 k 值撑起吞吐，而中位数低意味着尾延迟 SLO 被少数长轮次拖累。</p>\n\n<h3 id=\"alg-speculative-draft-verify-sec-15\">十五 · 残差分布的构造与一次性提交</h3>\n<p>首次拒绝处不是简单丢弃，而是从残差分布采样一个修正 token。残差定义为 max(0, p−q) 归一化，其质量恰好等于“目标想要但草稿没给够”的那部分概率。推导上这一步保证了边缘分布严格等于 p：接受分支贡献 min(p,q)，残差分支贡献 max(0,p−q)，两者相加逐位置还原 p。这就是“输出分布不变”的全部证明骨架，也是它能用于对正确性敏感的代码与工具调用场景的原因。</p>\n<p>伪代码落到可实现层面，核心是三个数组与一次前缀扫描：</p>\n<ul>\n<li>草稿阶段：对上下文做 γ 步自回归，缓存每步的 q_j 与候选 token，草稿 KV 单独存放，不与目标 KV 混写。</li>\n<li>验证阶段：把上下文加 γ 个候选拼成一条序列，目标模型一次前向得到每个位置的 p_j（对候选位置取对应 logits 的 softmax）。</li>\n<li>判定阶段：顺序扫描 j=1..γ，抽 u~Uniform(0,1)，若 u &lt; min(1, p_j/q_j) 则接受并继续，否则在此位置按残差分布采样修正 token、截断 j 之后所有候选，跳出。</li>\n<li>提交阶段：把接受前缀 k 个 token 的目标 KV 一次性写入主 KV cache，解码位置前进 k+1；草稿 KV 中对应被接受部分可直接复用为下一轮草稿的起点，被拒绝部分整段丢弃。</li>\n</ul>\n<p>代价落在 KV 管理上：验证前向会为目标模型的 γ 个候选位置各写一份 KV，若只接受 k 个，则 γ−k 份写入必须回滚。分页 KV 块管理在这里的价值是让回滚变成块表指针回退而非逐槽清零，但块粒度与 γ 的对齐关系直接决定浪费的显存带宽——γ 越大、接受率越低，回滚写入的无效带宽占比越高。长上下文下草稿与目标 KV 的一致性维护更复杂：草稿侧若复用被接受前缀的 KV，必须保证其位置编码与目标侧提交后的位置严格一致，否则下一轮草稿的 q 会系统性偏移，接受率悄悄下滑。</p>\n\n<h3 id=\"alg-speculative-draft-verify-sec-16\">十六 · 并行验证的算术强度账</h3>\n<p>验证阶段把 γ 个位置合并为一次前向，这是整个算法唯一真正“用满算力”的地方。逐 token 解码时每步只处理 1 个 token，矩阵乘退化为向量-矩阵乘，受内存带宽限制，GPU 的 tensor core 大量闲置；并行验证把有效 batch 维度从 1 抬到 γ，权重读取次数不变而计算量放大 γ 倍，算术强度随之上升，每 token 的内存带宽压力被摊薄。这是加速比的物理基础，与接受率无关——即使接受率不高，验证前向本身的效率也高于串行解码。</p>\n<p>但算术强度的收益有上限：γ 受限于草稿模型的自回归步数与显存中候选 KV 的占用，且验证前向的 attention 长度变成“上下文+γ”，长上下文下 attention 的二次项开始吃掉收益。工程上要算的是有效吞吐而非单轮加速：设目标模型单次前向时间为 T，草稿单步为 cT，则每轮耗时 (1+cγ)T、推进 E[k]+1 个 token，每 token 时间为 (1+cγ)T/(E[k]+1)。当上下文很长、T 本身被 attention 主导时，分母的 1 变大，γ 的最优点向小移动——这就是长上下文场景下必须调小 γ 的定量理由，而不是经验法则。</p>\n<p>具体例子：agent 循环中工具调用返回后需要续写一段结构化 JSON，草稿模型对字段名与括号的 q 高、对取值内容的 q 低。此时把 γ 设大，验证前向的 attention 长度被拉长、回滚写入增多，而接受长度被取值分歧点截断在中段，加速比反而低于中等 γ。可实现的策略是按“最近窗口接受长度中位数”而非均值调 γ，并对结构化段落临时抬高 γ、对自由文本段落压低 γ。</p>\n\n<h3 id=\"alg-speculative-draft-verify-sec-17\">十七 · γ 的动态调整与负载配比</h3>\n<p>把加速比公式对 γ 求极值，得到的最优条件是“边际接受增益等于边际草稿成本”：增加一个候选位置带来的 E[k] 增量，要能覆盖 c 的额外开销。由于连乘逐项衰减，边际增益随 γ 单调下降，因此最优点总在增益曲线与成本线的交点处。实现上不需要解方程，用滑动窗口估计最近若干轮的接受长度与草稿/验证耗时比，按梯度式步进调 γ 即可：接受长度上升则试探性增大 γ，连续多轮无提升则回退。</p>\n<p>负载配比的角度更硬：草稿模型与目标模型同驻显存，草稿权重与草稿 KV 直接挤压并发批大小。高并发小批的代码补全请求形态下，批大小下降会同时削弱目标模型验证前向的算术强度收益与吞吐，形成“为降延迟牺牲吞吐”的取舍。容量规划要把草稿显存计入每副本的固定开销，再按 SLO 的每 token 时延反推可承载的并发数；低延迟 SLO 下容量受限往往不是目标模型算力不够，而是草稿驻留把批大小压到了算术强度拐点以下。</p>\n<p>稳定性技巧是把 γ 的上界与草稿 KV 的块预算绑定：γ 个候选位置需要 γ 份草稿 KV 槽位，块预算不足时 γ 被动截断，此时应优先保证验证前向的连续性而非硬撑 γ。失败模式的另一半——长上下文 KV 一致性——在动态调 γ 时更易触发，因为 γ 变化会改变草稿侧复用的前缀长度，位置编码对齐必须在每次 γ 变更时重新校验。</p>\n\n<h3 id=\"alg-speculative-draft-verify-sec-18\">十八 · 可实现性边界与工程判断</h3>\n<p>把公式落到 kernel 层，接受判定是一次长度为 γ 的顺序扫描加一次残差采样，无法并行化（因为首次拒绝即截断），但它相对目标前向的耗时可以忽略；真正的实现难点在验证前向的 logits 收集——需要从“上下文+γ”序列中精确切出 γ 个候选位置的分布，且这些位置的 attention 必须看到全部前缀，不能因分块而漏看。用分页 KV 块表时，候选位置的块要预先分配并在拒绝后整段释放，块表操作的原子性决定回滚是否干净。</p>\n<p>工程判断可以归结为三条可检验的准则：其一，加速比公式里的 c 必须实测而非估算，草稿模型与目标模型的相对单步代价随精度配置（如草稿用低精度、目标用高精度）变化显著，c 估错会让 γ 调优整体偏移；其二，E[接受长度] 的估计要用分布而非均值，尾延迟 SLO 由长轮次的概率质量决定；其三，验证前向的 KV 回滚带宽要计入每 token 成本，长上下文下这部分可能超过草稿开销本身。三条准则共同指向同一个结论：投机草稿-并行验证的收益不是“开了就快”，而是由接受率分布、c 的实测值与 KV 回滚代价三者共同决定的、可计算的量。</p>\n<p>最后落在具体机制上：把 γ 的调整逻辑与块表回滚逻辑放在同一调度决策点，用最近窗口的接受长度中位数与实测 c 共同决定下一轮 γ，并同步预留对应数量的草稿 KV 块——这样 γ、显存与回滚代价三者被同一个决策闭环约束，负收益区间在调度层就被挡在门外，而不是等到端到端指标退化后才发现。</p>\n\n<h3 id=\"alg-speculative-draft-verify-sec-19\">十九 · 接受长度期望的推导边界与回滚代价</h3>\n<p>把加速比公式拆开看，边界条件就藏在分母里。期望接受长度 $\\mathbb{E}[k]=\\sum_{i=1}^{\\gamma}\\prod_{j=1}^{i}\\min(1,p_j/q_j)$ 的关键一步是把“前 $i$ 个位置全部被接受”的概率写成连乘——因为逐位置判定是独立进行的，第 $i$ 项只有在 $1..i-1$ 全接受时才有意义。当 $p_j\\ge q_j$ 时该项取 1，草稿与目标一致即无条件接受；当 $q_j$ 显著大于 $p_j$（草稿过度自信）时，$\\min$ 退化为 $p_j/q_j$，连乘迅速衰减。于是 $\\mathbb{E}[k]$ 对 $\\gamma$ 并非单调：$\\gamma$ 增大时求和项变多但每项乘积变短，而分母 $1+c\\gamma$ 里的草稿开销 $c$ 线性增长。求极值即令 $\\partial(\\mathbb{E}[k]+1)/(1+c\\gamma)/\\partial\\gamma=0$，工程上等价于“边际接受长度增益 = $c\\times$当前加速比”，这就是动态调 $\\gamma$ 的判据，而非拍脑袋取固定值。</p>\n<p>伪代码落到可实现层面，验证前向必须写成“先算后写”：目标模型对 $\\gamma$ 个候选位置并行前向得到 $p_1..p_\\gamma$，逐位置采样 $u\\sim U(0,1)$，若 $u\\le\\min(1,p_j/q_j)$ 则接受并继续，否则在位置 $j$ 从残差分布 $\\mathrm{norm}(\\max(0,p-q))$ 采样修正 token、截断 $j+1..\\gamma$，最后把 $1..k$ 连同修正 token 一次性提交 KV cache。这里的顺序不可颠倒——若边验证边写 KV，首次拒绝后已写入的后缀必须回滚，而 paged KV 的回滚是块级释放加元数据改写，长上下文下草稿与目标两套 KV 的块表还要保持位置对齐，一致性维护成本随上下文线性上升。</p>\n<p>失效条件有三类。其一是低接受率：代码补全里草稿模型对 API 签名、变量名的“猜测”若与目标模型的采样路径偏离，$\\mathbb{E}[k]$ 落到 1 附近，加速比 $\\approx 2/(1+c\\gamma)$ 在 $c\\gamma&gt;1$ 时小于 1，即负收益，此时唯一出路是把 $\\gamma$ 压到 1–2 或直接关闭投机。其二是显存挤压：草稿权重与目标权重同驻，验证阶段还要为 $\\gamma$ 个候选预留激活与 KV 写入空间，直接压缩可并发批大小，高并发小批的代码补全负载下吞吐反而下降。其三是长上下文：草稿自回归 $\\gamma$ 步每步都要读一遍上下文 KV，草稿侧带宽开销为 $\\gamma\\times$ 单 token 解码带宽，上下文越长这笔开销越难被验证阶段的算术强度收益抵消。</p>\n<table class=\"mini\"><thead><tr><th>条件</th><th>$\\mathbb{E}[k]$ 行为</th><th>系统代价落点</th></tr></thead><tbody><tr><td>$p_j\\ge q_j$ 普遍成立</td><td>接近 $\\gamma$，加速比高</td><td>验证前向算术强度收益主导</td></tr><tr><td>草稿过度自信 $q_j\\gg p_j$</td><td>连乘快速衰减至 1–2</td><td>草稿带宽开销超过验证收益</td></tr><tr><td>首次拒绝靠前</td><td>$\\gamma$ 个候选中大半丢弃</td><td>KV 回滚与块表改写成本上升</td></tr></tbody></table>\n<h3 id=\"alg-speculative-draft-verify-sec-20\">二十 · 请求形态的匹配：短 prompt、中等生成长度、高并发小批</h3>\n<p>投机草稿-并行验证的收益结构由两个比值决定：单位时间内草稿开销与验证开销的比，以及每次验证能兑现多少被接受的 token。前者由 γ 与草稿模型规模控制，后者由接受率决定。负载配方要做的，是把请求形态调整到这两个比值同时有利的区间。该算法面向的形态是短 prompt、中等生成长度、高并发小批：短 prompt 意味着验证前向中上下文部分的 KV 读取占比低，γ 个候选位置带来的算术强度提升更容易摊薄每 token 的内存带宽成本；中等生成长度意味着草稿模型有足够多的连续解码步来摊销其权重加载与显存占用，而不会像超短生成那样在固定开销上亏本；高并发小批则让多个请求的验证前向拼进同一批，把 γ 个位置的空闲算力填满。</p>\n<p>反过来，长 prompt 加超短生成的形态（例如一次问答只吐十几个 token）会让草稿模型付出与收益不成比例：草稿权重要加载、草稿 KV 要建立，而目标模型只验证寥寥几步。此时加速比公式中的分母 1+cγ 里 c 主要由草稿单步成本与目标单步成本之比决定，草稿的相对开销被固定启动成本抬高，接受长度带来的分子增益不足以抵消。工程判断是：把这类请求留在纯目标模型路径上，或者用更小的 γ（甚至 γ=1）降低 c，而不是强行套用投机。</p>\n<p>长度分布还影响尾延迟。生成长度分布长尾时，少数超长请求会在解码循环里反复触发验证前向，占用批内位置，把短请求的每 token 时延推高。配方上需要按长度分桶或按 SLO 分级：低延迟 SLO 的短请求走小 γ、小批，长请求走较大 γ 但独立批，避免同一批内 γ 与生成长度错配导致尾延迟劣化。</p>\n\n<h3 id=\"alg-speculative-draft-verify-sec-21\">二十一 · 并发与批大小的耦合：γ 挤占的是位置预算</h3>\n<p>验证前向把 γ 个候选位置合并为一次前向，这在算术强度上是好事，但在批调度上是坏事：每个请求在验证步占用的位置数从 1 变成 γ。批大小 B 与 γ 的乘积构成一次前向的位置总量，受限于显存中 KV 的可用块数与计算单元的占用上限。也就是说，投机不是免费的并行度，它把并发从“请求数”换算成“请求数×γ”的位置预算。</p>\n<div class=\"formula\">$$\\text{位置预算}=B\\cdot\\gamma\\le \\text{KV 块容量}/\\text{每位置 KV 开销},\\quad \\text{加速比}\\approx\\frac{\\mathbb{E}[\\text{接受长度}]+1}{1+c\\gamma}$$</div>\n<p>当并发上升而 KV 块容量不变时，调度器只有两个选择：降低 B 以维持 γ，或降低 γ 以维持 B。前者牺牲吞吐（批内请求少，验证前向的算术强度下降），后者牺牲单请求时延（接受长度变短，每步前进的 token 少）。配方上的经验方向是让 γ 随并发反向调整：低并发时用大 γ 换时延，高并发时用小 γ 保吞吐，使 B·γ 稳定在容量附近而不是撞墙。</p>\n<p>具体例子：一个代码补全服务在并发爬升时若固定 γ=4，位置预算迅速吃满 KV 块，调度器被迫把 B 从数十降到个位数，验证前向从“填满算力”退化为“小批高延迟”，端到端每 token 时延反而比不开投机更差。把 γ 降到 2 并保持 B，接受长度期望下降但批内位置利用率回升，尾延迟回到 SLO 内。这说明 γ 不是越大越好，它是与 B 共享同一份显存预算的旋钮。</p>\n\n<h3 id=\"alg-speculative-draft-verify-sec-22\">二十二 · 接受率的负载依赖性：任务分布决定 γ 的最优点</h3>\n<p>接受率不是模型属性，而是任务属性。代码补全中，局部上下文强约束下一个 token 的取值（缩进、括号、已出现的标识符），草稿模型与目标模型的分布高度重合，逐位置接受概率高，接受长度期望接近 γ；agent 循环中工具调用参数、自然语言推理段落、开放式续写的分布更发散，草稿容易在早期位置被拒，接受长度期望骤降。公式里逐位置乘积结构意味着接受率是乘性的：单位置接受概率从 0.9 降到 0.7，γ=4 时接受长度期望的下降幅度远大于线性。</p>\n<p>低接受率的代价是双重的：草稿开销照付，而验证前向只兑现了 k 个 token（k 很小），首次拒绝处还要从残差分布 $$\\max(0,\\ p-q)$$ 归一化后采样一个修正 token，等于用一次完整的目标前向换来了接近一次普通解码的产出。此时加速比公式的分子趋近于 2 而分母仍是 1+cγ，cγ 越大亏得越多。失败模式正是“低接受率时草稿开销超过验证收益，加速比退化甚至出现负收益”。</p>\n<p>配方上的应对是按任务类型与在线接受率动态调 γ：以近期窗口的接受长度估计为反馈信号，接受长度高则增大 γ 摊薄固定开销，接受长度低则收缩 γ 直至退回纯目标解码。工程上要把这个反馈回路做在调度层而非模型层，使 γ 的调整粒度与批调度周期对齐，避免每个请求单独调参带来的抖动。</p>\n\n<h3 id=\"alg-speculative-draft-verify-sec-23\">二十三 · 显存与并发的挤压：草稿模型同驻的容量账</h3>\n<p>草稿模型额外占用显存与算力，与目标模型同驻时挤压并发批大小。硬件档位需同时容纳草稿与目标权重及其 KV：目标权重是固定大头，草稿权重是第二份固定开销，而两套 KV 在长上下文下都要按位置增长。容量账可以写成：可用 KV 预算 = 总显存 − 目标权重 − 草稿权重 − 运行时预留，再除以每位置 KV 开销得到最大位置数，位置数再除以 γ 得到有效并发。草稿权重每增加一份，有效并发就下降一档。</p>\n<p>这就是为什么负载配方必须把草稿模型规模当作容量参数而非精度参数：草稿太小则接受率不足，草稿太大则并发被挤压，两者都让加速比退化。在低延迟 SLO 下容量受限尤其明显——SLO 要求尾延迟，尾延迟由批内最慢请求决定，而批大小被草稿权重压缩后，调度器更难用大批来平滑抖动。</p>\n<p>长上下文还带来一致性维护成本：验证前向的 KV 写入与回滚需要额外缓存管理，草稿与目标 KV 在长上下文下的一致性维护复杂。未接受候选的 KV 必须回滚，接受前缀的 KV 必须一次性提交，这两步在分页块管理下是块级的分配与释放操作，长上下文意味着更多块参与，回滚路径的元数据开销随上下文长度上升。配方上应把长上下文请求与短上下文请求分开批处理，避免长上下文请求的回滚开销拖累短请求的验证步。</p>\n\n<h3 id=\"alg-speculative-draft-verify-sec-24\">二十四 · 负载不对时的三种退化形态与判别信号</h3>\n<p>第一种退化是“草稿空转”：请求形态为长 prompt 超短生成，草稿模型完成 γ 步自回归后目标模型只验证一次就结束，草稿的固定开销无法摊销。判别信号是平均生成长度接近 γ，且草稿调用次数与目标验证次数之比接近 1。处置是把这类请求路由到纯目标路径。</p>\n<p>第二种退化是“验证挤批”：并发高、γ 固定偏大，位置预算 B·γ 撞上 KV 容量，批大小被迫压缩，验证前向的算术强度反而下降。判别信号是批大小随并发上升而下降、每 token 时延随并发上升而上升（与常规吞吐曲线相反）。处置是让 γ 随并发反向调整，把 B·γ 稳定在容量附近。</p>\n<p>第三种退化是“接受率塌陷”：任务分布发散（开放式生成、多轮 agent 的自由文本段），单位置接受概率低，接受长度期望远小于 γ，残差修正采样频繁触发。判别信号是接受长度与 γ 的比值持续走低、每步前进 token 数接近 1。处置是按任务类型分段调 γ，必要时对该任务关闭投机。</p>\n<table class=\"mini\"><thead><tr><th>退化形态</th><th>触发负载特征</th><th>判别信号</th><th>处置</th></tr></thead><tbody><tr><td>草稿空转</td><td>长 prompt、超短生成</td><td>生成长度≈γ，草稿/验证次数比≈1</td><td>路由到纯目标路径</td></tr><tr><td>验证挤批</td><td>高并发、γ 固定偏大</td><td>批大小随并发下降，时延反向上升</td><td>γ 随并发反向调整</td></tr><tr><td>接受率塌陷</td><td>开放式生成、自由文本段</td><td>接受长度/γ 持续走低</td><td>按任务分段调 γ 或关闭</td></tr></tbody></table>\n<p>三种退化共享一个根因：γ 与负载的匹配是动态的，而静态配方在负载漂移时必然落入某一侧。工程判断是把 γ 当作调度器的运行时变量，用接受长度与位置预算两个反馈量联合调节，而不是把它写死在部署配置里。判别信号要能在调度周期内观测到，否则反馈回路滞后于负载变化，退化形态会在切换窗口内持续存在。</p>\n\n<h3 id=\"alg-speculative-draft-verify-sec-25\">二十五 · 配方落点：把 γ 与路由做成调度层决策</h3>\n<p>负载配方的落点不在模型内部，而在调度层：请求进入时按形态（prompt 长度、预期生成长度、任务类型）打标签，标签决定初始 γ 与是否走投机路径；运行中以接受长度为反馈调整 γ，以位置预算为约束调整批组成。这个决策的数据流与验证前向的 KV 提交/回滚解耦，避免调度抖动传导到缓存管理。</p>\n<p>一个可操作的伪代码思路是：对每个调度周期，先按任务标签给出 γ 的上下界，再按当前 KV 块余量计算可承受的 B·γ，取两者交集的中点作为本周期的 γ；若观测到的接受长度低于阈值，则下调 γ 并提高纯目标路径的流量比例。这样做的代价是调度器需要维护每任务的接受率统计，收益是把三种退化形态挡在 SLO 之外。</p>\n<p>配方与硬件档位的关系也在此收束：草稿与目标同驻的显存账决定了位置预算的上限，而位置预算又决定了 γ 与 B 的可行组合。负载不对时，问题往往不是算法失效，而是配方把 γ 放在了容量与接受率都不支持的区间。把 γ 从部署常量改成调度变量，并让路由按请求形态分流，是这套算法在真实服务里稳定兑现加速比的前提。</p>\n\n<h3 id=\"alg-speculative-draft-verify-sec-26\">二十六 · 负载配方：短提示、中等生成、高并发小批才是它的主场</h3>\n<p>这一节只谈边界。投机草稿-并行验证的收益结构由加速比公式直接决定：<div class=\"formula\">$$\\text{加速比}\\approx\\frac{\\mathbb{E}[\\text{接受长度}]+1}{1+c\\gamma}$$</div>其中 c 是草稿成本与单次目标前向成本之比，γ 是候选长度。分母随 γ 线性增长，分子只随接受长度增长——这意味着负载必须同时满足两个条件：接受长度足够长，且单步目标前向足够“贵”（即内存带宽受限而非算力受限）。代码补全与 agent 循环恰好落在交集里：短 prompt、中等生成长度、高并发小批，每步解码只搬权重不干活，算术强度低，把 γ 个位置合并成一次前向正好把闲置算力换成带宽节省。反过来，长 prompt 的预填阶段本就算术密集，验证前向的边际收益被稀释；超长生成则让草稿模型的自回归开销按 γ 线性累积，c 上升，加速比被分母吃掉。</p>\n<p>失效条件可以列成一张对照表，工程上按它做准入判断：</p>\n<table class=\"mini\"><thead><tr><th>负载形态</th><th>接受长度</th><th>主要代价</th><th>结果</th></tr></thead><tbody><tr><td>短 prompt + 中等生成 + 高并发小批</td><td>高</td><td>草稿显存挤占批大小</td><td>正收益，尾延迟改善</td></tr><tr><td>结构化输出 / 工具调用</td><td>高且稳定</td><td>KV 回滚管理</td><td>正收益，分布严格一致</td></tr><tr><td>开放域长文创作</td><td>低</td><td>草稿开销超过验证收益</td><td>加速比退化甚至负收益</td></tr><tr><td>长上下文多轮 agent</td><td>中</td><td>草稿与目标 KV 一致性维护</td><td>收益被缓存管理吃掉</td></tr></tbody></table>\n<p>负载不对时的系统代价有三个具体出口。其一是接受率塌陷：低接受率下草稿模型每步仍要自回归跑 γ 次小前向，这些前向本身也是带宽受限的，草稿开销超过验证收益，端到端时延反而高于朴素解码，此时唯一止血手段是按接受率动态调 γ，把 γ 压到接近 1 退化为普通解码。其二是显存挤压：草稿与目标权重同驻，加上两套 KV，直接压缩可用的并发批大小，在低延迟 SLO 下容量规划按“有效批大小”而非“峰值批大小”算，高并发小批的配方会被显存而不是算力卡住。其三是 KV 回滚：验证前向对 γ 个位置一次性写入 KV，首次拒绝处截断后续候选，被丢弃位置的 KV 必须回滚，长上下文下草稿与目标两套 KV 的一致性维护复杂，这部分开销不体现在加速比公式里，却实打实落在尾延迟上。判断是否上这套方案，先测目标负载的实际接受长度分布，再算 cγ 与接受长度加一的比值，比值不占优就不要上。</p>\n<h3 id=\"alg-speculative-draft-verify-sec-27\">二十七 · 硬件档位：把草稿与目标的驻留预算一起算</h3>\n<p>部署投机草稿-并行验证时，第一个决策不是选草稿模型，而是先算清“双模型同驻”的显存账。目标模型权重、草稿模型权重、两套 KV cache、验证前向的临时激活，四项必须同时落在同一组 SM 的 HBM 预算内。Blackwell 的 B200/B300 单卡 HBM 容量与 GB200/GB300 NVL72 的机柜级统一池化是两种完全不同的档位选择：单卡档位适合把草稿与目标压在同一张卡上做紧耦合验证，机柜档位则允许把草稿放在独立 GPU、通过 NVLink 5 传候选 token 与概率向量。</p>\n<p>关键判断量是“每 GPU 可用 KV 预算”。设目标权重占用 $W_t$、草稿权重 $W_d$、每 token 每层 KV 字节为 $b_{kv}$、层数 $L$、并发批 $B$、上下文长度 $S$，则单卡可行条件为：</p>\n<div class=\"formula\">$$W_t + W_d + 2 \\cdot B \\cdot S \\cdot L \\cdot b_{kv} + A_{\\text{verify}} \\le C_{\\text{HBM}}$$</div>\n<p>系数 2 来自草稿与目标各持一份 KV；$A_{\\text{verify}}$ 是 γ 个位置并行前向的激活峰值，随 γ 线性增长。工程上常见的错误是先按目标模型单独跑满并发，再“顺手”加一个草稿模型，结果 KV 预算被权重挤掉，连续批处理的有效批大小骤降，尾延迟反而恶化。正确做法是把草稿权重视为固定开销，先扣掉它再分配 KV 块，这与分页 KV 块管理的块表设计直接耦合——块池容量必须按扣除双权重后的余量重算。</p>\n<p>具体例子：在单卡档位部署一个中等规模目标模型加一个 1–2B 级草稿模型时，草稿权重占比虽小，但两套 KV 使同等并发下 KV 占用翻倍，容量规划须以“目标单独部署时的 KV 预算减半”为起点反推并发上限，而不是沿用原并发数。</p>\n\n<h3 id=\"alg-speculative-draft-verify-sec-28\">二十八 · 并行拓扑：验证前向的切分方式决定通信代价</h3>\n<p>验证阶段把 γ 个候选位置合并成一次前向，这次前向的张量形状是 $[B, \\gamma+1, H]$（含当前 token），算术强度高于逐 token 解码，因此它天然更适合张量并行。但草稿模型是逐 token 自回归的，每步只处理一个位置，通信-计算比极差，张量并行在草稿侧几乎必然亏本。于是拓扑出现分叉：草稿走单卡或纯数据并行，目标走张量并行加专家并行。</p>\n<p>对 MoE 目标模型，验证前向的 γ+1 个位置会触发多次专家路由，all-to-all 通信量与 γ 成正比。此时若草稿与目标跨节点，候选 token 与 $q$ 概率向量的传输会叠加在 all-to-all 之上。NVL72 机柜内 NVLink 5 的高带宽域能把这两类流量压在同一域内，跨机柜则必须让草稿与目标同处一个 NVLink 域，否则验证前向的启动延迟会吃掉并行打分带来的收益。</p>\n<p>伪代码思路：草稿侧按数据并行复制，每个副本独立生成 γ 个候选；目标侧按张量并行切分，验证前向前把各副本的候选拼成一个验证批，一次前向产出全部 $p$。这样草稿的串行延迟被数据并行摊薄，目标的并行验证保持高算术强度。代价是验证批的批大小随草稿副本数增长，$A_{\\text{verify}}$ 峰值上升，需要与 KV 预算联动。</p>\n<p>具体例子：agent 循环中单请求的 γ 较小但并发请求多，把多个请求的候选合并成一个验证批，比给单请求加大 γ 更能填满目标模型的 SM；而在代码补全的低并发场景，则应减少草稿副本、把 γ 调大以提升单请求的算术强度。</p>\n\n<h3 id=\"alg-speculative-draft-verify-sec-29\">二十九 · 量化方案：草稿与目标的精度不必对齐</h3>\n<p>接受判定依赖 $p/q$ 的比值，这带来一个容易被忽视的约束：草稿概率 $q$ 与目标概率 $p$ 必须来自同一数值语义下的分布，否则 $\\min(1,p/q)$ 会被量化误差系统性偏移。工程上的稳妥做法是草稿用较低精度（如 FP8）做前向以压低延迟，但在输出层把 logits 反量化到与目标一致的精度再归一化出 $q$；目标模型用 NVFP4 或 FP8 做权重与激活，验证前向的输出层同样保持较高精度以稳定 $p$。</p>\n<p>目标与草稿联合量化的细节属于另一条目的主题，此处只指出部署侧的判断：验证前向的 γ+1 个位置共享同一份权重，权重量化的误差在这些位置上高度相关，不会像独立采样那样相互抵消，因此目标侧量化的校准集必须覆盖长上下文与结构化输出形态，否则接受率会在特定任务上无声塌陷。</p>\n<p>代价方面，NVFP4 把目标权重压到四分之一，直接释放出可观的 KV 预算，使双模型同驻成为可能；但验证前向的激活若也用低精度，残差分布 $\\max(0,p-q)$ 的归一化会放大舍入噪声，表现为接受前缀在边界位置频繁被截断。具体例子：工具调用场景中 JSON 结构的括号与字段名位置对概率微小差异极敏感，这些位置一旦因量化偏移被拒绝，修正 token 会打断结构，端到端时延因重试而上升。</p>\n\n<h3 id=\"alg-speculative-draft-verify-sec-30\">三十 · KV 策略：提交、回滚与一致性</h3>\n<p>接受前缀长度 $k$ 个 token 一次性提交到 KV cache，未接受候选丢弃——这句话在部署上意味着 KV 写入必须是“先写后裁”的。验证前向会为 γ+1 个位置全部算出 K/V 并写入临时区，接受判定后才把前 $k$ 个位置的 KV 提升为正式块，其余回滚。若直接写入正式 KV 再裁剪，回滚需要块级垃圾回收，长上下文下会与分页块表产生碎片竞争。</p>\n<p>推荐策略是双缓冲：验证前向写入一块独立的暂存 KV 区，其块表与正式块表分离；接受后按 $k$ 做块级拷贝或指针交换。这样回滚成本是 O(1) 的指针丢弃，而不是逐位置清零。代价是暂存区需要额外 $\\gamma+1$ 个位置的 KV 容量，在 γ 动态调大时这块预留要同步扩容，否则会成为隐式的并发上限。</p>\n<p>草稿与目标的 KV 一致性是第二个难点。草稿模型有自己的 KV，其上下文必须与目标已提交的前缀严格同步；每次接受 $k$ 个 token 后，草稿 KV 要前进 $k$ 步，而被拒绝的候选在草稿侧已写入的 KV 必须截断。工程上让草稿 KV 也走暂存区、只提交与目标一致的前缀，可避免两侧位置漂移。具体例子：长上下文 agent 循环中，若草稿 KV 未及时截断，下一轮草稿会基于“幻觉历史”生成候选，接受率持续下滑，加速比退化为负——这正是低接受率失败模式在部署层的根因之一。</p>\n\n<h3 id=\"alg-speculative-draft-verify-sec-31\">三十一 · 调度参数：γ 的闭环控制与批的耦合</h3>\n<p>γ 不是静态超参，而是闭环控制量。加速比近似为 $(\\mathbb{E}[\\text{接受长度}]+1)/(1+c\\gamma)$，其中 $c$ 是草稿单 token 成本与目标单次验证成本的比值。对 $\\gamma$ 求极值可知最优 γ 随接受率上升而增大、随 $c$ 上升而减小。部署上应把最近若干批的实测接受长度作为反馈信号，用简单的比例控制调整 γ，并设上下界防止振荡。</p>\n<p>调度器还要处理 γ 与连续批处理的耦合：γ 变大意味着验证批的序列长度变长，单批占用的 KV 暂存与激活峰值上升，可容纳的并发请求数下降。因此在低延迟 SLO 下，调度器应在“大 γ 少并发”与“小 γ 多并发”之间按尾延迟目标切换。具体判据是：当排队延迟已接近 SLO 余量时，优先减小 γ 换并发；当单请求时延是瓶颈时，优先加大 γ 提算术强度。</p>\n<p>可复现的配置思路可以固化为四步：第一步按第一节的不等式反推并发上限，把草稿权重作为固定扣除项；第二步按请求形态选拓扑，低并发单请求走单卡紧耦合、高并发走草稿数据并行加目标张量并行；第三步量化上草稿低精度前向、输出层对齐目标精度，目标侧校准集覆盖结构化输出；第四步 KV 走双缓冲暂存加指针交换，γ 用接受长度闭环控制并设界。每一步的验证指标分别是有效批大小、验证前向启动延迟、接受率与尾延迟，四者任一恶化都说明该步配置与负载配方不匹配。</p>\n<p>最后落在工程判断上：这套配方的稳定性不取决于单点最优，而取决于 γ 闭环与 KV 暂存容量的联动——γ 上调时暂存区必须同步扩容，否则调度器会在无告警的情况下被隐式并发上限卡住，表现为接受率正常但吞吐不再随并发增长。</p>\n\n<h3 id=\"alg-speculative-draft-verify-sec-32\">三十二 · 配方边界：草稿与目标同驻时的显存账、γ 的失效区间与 KV 回滚代价</h3>\n<p>把草稿-验证配方落到可复现的部署上，第一笔账不是算力而是显存：草稿与目标权重及其 KV 必须同时驻留，草稿占用的每一份 HBM 都直接挤压目标模型的并发批大小，而低延迟 SLO 下的容量恰恰由批大小决定。配置思路因此从约束反推：先按目标模型的权重加 KV 定出每卡可承载的并发上限，再把草稿塞进剩余余量——若余量不足以容纳草稿权重加其 KV，就不要走同卡同驻，而是把草稿放到独立档位（另一张卡或另一组 SM），用一次额外的前向往返换目标侧的批空间。量化方案上，目标侧用 NVFP4/FP8 压缩权重与 KV 以腾出余量，草稿侧则倾向更激进的低比特，因为草稿只影响提议质量、不影响输出分布；但草稿量化过狠会拉低 $q$ 与 $p$ 的重合度，接受率下滑，此时省下的显存会被 γ 的补偿性放大吃掉。</p>\n<p>γ 的取值不是调参偏好，而是一条有明确失效区间的收益曲线。按 $\\mathbb{E}[\\text{接受长度}]=\\sum_{i=1}^{\\gamma}\\prod_{j=1}^{i}\\min(1,p_j/q_j)$ 与 $\\text{加速比}\\approx(\\mathbb{E}[\\text{接受长度}]+1)/(1+c\\gamma)$，其中 $c$ 是草稿单 token 开销相对目标单次验证前向的比例。当任务从代码补全（上下文强约束、接受率高）切到 agent 循环中的自由文本工具调用参数生成（分布发散、接受率低）时，$\\prod$ 项迅速衰减，分子趋近 1，而分母随 $\\gamma$ 线性增长——加速比跌破 1 的临界点由 $c$ 与实测接受率共同决定，越过即负收益。工程判断是给 γ 设上下界并在运行时按滑动窗口接受率调整：接受率高位时放大 γ 摊薄验证前向的固定开销，低位时收缩到 1–2 并保留关闭投机回退到纯自回归的开关。调度参数上，连续批处理需把草稿步与验证步视为两个可独立成批的阶段，验证前向因合并 γ 个位置而算术强度高、适合大 batch，草稿步则是典型带宽受限的小 batch，二者混批会互相拖累。</p>\n<p>KV 策略是本配方最容易被低估的系统代价。接受前缀 k 个 token 一次性提交、解码位置前进 k+1，意味着验证前向已经为全部 γ 个候选写入了 KV，未接受部分必须回滚——回滚不是逻辑删除，而是要把 KV 指针与页表恢复到接受前缀末尾，长上下文下草稿与目标的 KV 一致性维护因此变复杂：草稿侧若维护独立 KV，每次拒绝都要与目标侧对齐；若共享，则草稿的自回归写入会污染目标页。可复现的做法是给验证前向分配一块临时 KV 暂存区，接受后按 k 拷贝进主 KV，拒绝则整块丢弃，代价是每次验证多一次 k 长度的 KV 拷贝带宽，在长上下文、高并发下这笔拷贝会与目标权重读取争抢 HBM 带宽。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>观测信号</th><th>配方动作</th></tr></thead><tbody><tr><td>接受率低位</td><td>加速比趋近或低于 1</td><td>收缩 γ，必要时关闭投机</td></tr><tr><td>草稿挤占批空间</td><td>并发批大小下降、尾延迟抬升</td><td>草稿移出同卡或降比特</td></tr><tr><td>长上下文回滚</td><td>KV 拷贝带宽占比上升</td><td>临时暂存区加按 k 提交</td></tr></tbody></table>\n<h3 id=\"alg-speculative-draft-verify-sec-33\">三十三 · 显存占用：草稿权重与 KV 的双重挤压</h3>\n<p>投机草稿-并行验证在系统层面的第一道代价来自显存。草稿模型虽然“廉价”，但它是一份独立的权重，必须与目标模型同驻同一组 GPU。在 Blackwell 的部署语境下，这意味着一台 B200 或一个 GB200 NVL72 机柜里，原本按目标模型权重加 KV cache 规划的显存预算，被硬生生切走一块给草稿。切走的不只是权重：草稿模型有自己的 KV cache，目标模型有另一套 KV cache，验证阶段还要为 γ 个候选位置预留写入空间。三者叠加，显存账本从“一份权重 + 一份 KV”变成“两份权重 + 两份 KV + 验证暂存”。</p>\n<p>把账算细一点。设目标模型权重显存为 W_t，草稿模型权重为 W_d，每 token 每层的 KV 字节数为 s，层数为 L，上下文长度为 n，批大小为 B。则目标 KV 约为 2·B·n·L·s（K 与 V 各一份），草稿 KV 同构但层数与头数可能更小。验证阶段还需要在 γ 个候选位置上持有目标模型的中间激活与待提交的 KV 条目，这部分随 γ 线性增长。显存约束可写成：</p>\n<div class=\"formula\">$$W_t + W_d + 2B n L s + 2B n_d L_d s_d + \\gamma \\cdot \\Delta_{\\text{verify}} \\le M_{\\text{GPU}}$$</div>\n<p>其中 Δ_verify 是每个候选位置验证时额外占用的激活与暂存。这个不等式直接决定了并发批大小 B 的上限。工程上最直接的观察是：草稿模型占走的每一字节显存，都是从 B 里扣出来的。而 B 一旦下降，解码阶段每步的内存带宽利用率随之下降——因为权重读取的固定开销被摊到更少的请求上。这就是为什么在低延迟 SLO 场景下，草稿模型的显存代价会以“挤压并发”的形式二次放大。</p>\n<p>具体例子：代码补全服务在 GB200 上以目标模型加草稿模型同驻，草稿选用层数更少、隐藏维度更小的同族小模型。若目标模型权重已占去单卡显存的主要部分，草稿权重再占一成到两成，KV 预算被压缩，连续批处理能容纳的请求数下降，尾延迟在高峰时段首先恶化。这不是接受率的问题，而是容量问题——即使接受率很高，显存不够就是不够。</p>\n\n<h3 id=\"alg-speculative-draft-verify-sec-34\">三十四 · 带宽：验证前向的算术强度红利与草稿的带宽税</h3>\n<p>投机解码的收益来源，本质上是一次算术强度的置换。自回归解码每步只处理一个 token，矩阵乘退化为矩阵-向量乘，权重读取的字节数远大于计算量，GPU 的算力大量闲置，瓶颈在 HBM 带宽。并行验证把 γ 个候选位置合并成一次前向，矩阵-向量乘变成矩阵-矩阵乘，同一批权重被复用 γ 次，算术强度提升约 γ 倍，每 token 的带宽压力显著下降。这是收益侧。</p>\n<p>代价侧同样在带宽上。草稿模型自回归生成 γ 个候选，是 γ 次串行的单 token 前向，每一次都受带宽限制，且草稿权重本身也要从 HBM 读出。草稿的带宽开销近似为 γ 次权重读取，加上草稿 KV 的读写。于是每接受一个 token 的系统带宽账为：目标验证一次前向的权重读取（摊薄后约 1/γ 的每 token 带宽）加上草稿 γ 次前向的权重读取（每 token 约 c 倍目标单步带宽，c 为草稿与目标单步开销之比）。加速比公式里的分母 1+cγ 正是这笔账的浓缩：</p>\n<div class=\"formula\">$$\\text{加速比}\\approx\\frac{\\mathbb{E}[\\text{接受长度}]+1}{1+c\\gamma}$$</div>\n<p>当 c 接近 1（草稿模型与目标模型规模相当），分母随 γ 线性膨胀，加速比迅速被吃掉；只有当 c 显著小于 1，γ 的增大才划算。Blackwell 上的工程判断是：草稿模型必须足够小，使 c 落在零点几的量级，否则带宽税超过算术强度红利。另一个常被忽略的点是验证前向的 KV 写入带宽——接受前缀 k 个 token 要一次性写入目标 KV cache，未接受的候选要回滚丢弃，写入与回滚都产生额外的 HBM 流量，长上下文下这部分不可忽视。</p>\n<p>具体例子：agent 循环中单次工具调用后追加一段中等长度上下文，草稿模型逐 token 生成 γ 个候选，每步都触发一次全量权重读取；若草稿层数只比目标少一两层，c 偏大，γ 取大值时端到端时延反而上升。此时正确做法是压低 γ，让分母的 cγ 项受控。</p>\n\n<h3 id=\"alg-speculative-draft-verify-sec-35\">三十五 · 通信：并行验证在张量并行与分离式部署下的放大</h3>\n<p>当目标模型跨多卡张量并行（TP）部署时，验证前向的每一次 all-reduce 或 reduce-scatter 都被 γ 个位置放大——不是通信量放大 γ 倍（通信量与 token 数成正比，确实放大），而是通信次数与延迟结构被改变。自回归解码时每步一次通信、延迟主导；并行验证时一次前向处理 γ 个位置，通信量增大但通信次数不变，单次通信的字节数上升，带宽主导。在 NVLink 5 提供的机内带宽下，这通常是有利的：大消息摊薄了固定延迟。但在跨节点场景，比如 GB200 NVL72 机柜内不同 NVLink 域之间，或分离式预填/解码架构中预填节点与解码节点之间，验证前向的激活传输量随 γ 增长，NIXL 之类的传输层要搬运的字节数上升。</p>\n<p>草稿模型的位置选择直接决定通信形态。若草稿与目标同卡同 TP 组，草稿的 γ 次串行前向各自触发一次 TP 通信，通信次数为 γ 次，延迟叠加；若草稿放在单卡上不切分，则草稿无 TP 通信，但草稿与目标之间的概率 q 与 p 需要对齐——这要求两边词表一致，否则接受判定无法逐位置比较。词表对齐在多卡部署下意味着草稿输出的 logits 要跨卡汇聚或做分布式采样，这又是一笔通信。</p>\n<p>具体例子：NVL72 机柜内以 TP=8 部署目标模型，草稿模型以 TP=1 挂在其中一张卡上。验证阶段 γ 个位置合并前向，TP 组内 all-reduce 消息变大但次数不变，机内 NVLink 带宽足以吸收；草稿阶段 γ 次单卡前向不产生 TP 通信，但草稿卡成为热点，其 HBM 带宽成为瓶颈。若把草稿也切成 TP=2，草稿阶段的通信次数翻倍，低 γ 时延迟反而更差。</p>\n\n<h3 id=\"alg-speculative-draft-verify-sec-36\">三十六 · 功耗与热：验证前向的功率尖峰</h3>\n<p>并行验证把 γ 个位置塞进一次前向，矩阵乘的规模从向量级跳到矩阵级，SM 的利用率瞬间拉高，功耗随之出现尖峰。自回归解码时 GPU 长期处于低利用率、低功耗状态，算力闲置；投机验证则把这种闲置转化为短时高功率爆发。在 GB200 这类高密度机柜里，功率尖峰的工程含义是：机柜级功率预算与散热能力必须按峰值而非均值规划。若同一机柜内多路服务同时进入验证阶段，功率叠加可能触发降频，而降频直接打击验证前向的延迟——这恰恰是低延迟 SLO 最敏感的部分。</p>\n<p>草稿模型的功耗形态相反：γ 次串行小前向，每次利用率低、功耗低，但持续时间长。两者的组合使单请求的功率曲线呈“长低尾 + 短高峰”。容量规划时若按平均功率配置，高峰时段的降频风险被低估。工程上的缓解手段包括错开验证时机（不同请求的 γ 相位错开）、限制单卡并发验证数、以及在功率受限档位下主动压低 γ——因为 γ 越大，单次验证的功率尖峰越高。</p>\n<p>具体例子：一个高并发小批的代码补全服务，数百个请求的验证阶段在时间上随机分布，单卡上同时进入验证的请求数受连续批处理调度控制。若调度器不感知功率，峰值时段多请求验证叠加，SM 降频，尾延迟抬升；把 γ 与并发验证数纳入调度约束后，功率曲线被削平，尾延迟回落。</p>\n\n<h3 id=\"alg-speculative-draft-verify-sec-37\">三十七 · 尾延迟：接受率分布的长尾与回滚成本</h3>\n<p>吞吐看均值，SLO 看尾延迟。投机解码的尾延迟由两个分布共同决定：接受长度 k 的分布，以及草稿生成 γ 个候选所需时间的分布。接受长度不是常数，它随上下文内容剧烈波动——代码补全中缩进、括号、常见 API 调用模式接受率高，而 agent 循环中工具返回后的自由文本生成接受率低。低接受率请求的端到端时延接近“草稿 γ 次 + 验证一次 + 只前进一个 token”，即纯亏。尾延迟的恶化正来自这批低接受率请求：它们付出了草稿的全部代价，却只换来最小前进量。</p>\n<p>回滚成本进一步放大尾部。首次拒绝处要从残差分布采样修正 token 并截断后续候选，已写入的候选 KV 要丢弃。若 KV 按分页块管理，回滚意味着块表的回退与块的回收，长上下文下块表操作的开销随上下文长度增长。更麻烦的是草稿与目标两套 KV 的一致性维护：草稿 KV 在拒绝后要截断到接受前缀，目标 KV 只提交接受部分，两边位置指针必须同步。任何同步失误都会在后续步骤中以错误上下文的形式暴露，且难以定位。</p>\n<p>工程判断是：尾延迟控制不能只靠动态调 γ 的均值逻辑，而要对接受率做分位监控。当低分位接受率跌破阈值时，对该类请求直接关闭投机、退回纯自回归，用确定性换尾延迟。这比让低接受率请求在投机路径上反复亏损更稳。具体例子：agent 循环中工具调用返回结构化 JSON 的片段接受率高，而工具返回后的自然语言总结接受率低；按请求类型分流，结构化片段走投机，自由文本走纯解码，尾延迟分布被截断。</p>\n\n<h3 id=\"alg-speculative-draft-verify-sec-38\">三十八 · 规模上去以后哪里先崩</h3>\n<p>把规模推上去，崩溃的顺序有明确的工程次序。第一崩的是显存容量：草稿权重与双份 KV 挤压并发批大小，B 下降，吞吐与带宽利用率同步下滑。第二崩的是低接受率请求的尾延迟：并发越高，低接受率请求在队列中的占比越不可忽略，它们占用草稿算力却不产生前进量，等效于用稀缺的验证带宽补贴无效草稿。第三崩的是功率与降频：验证阶段的功率尖峰在高并发下叠加，触发降频，反过来打击验证延迟。第四崩的才是通信——在 NVLink 5 域内，通信通常不是首个瓶颈，除非草稿与目标跨域部署或词表对齐引入额外汇聚。</p>\n<p>这个次序给出的容量规划原则是：先按显存定并发上限，再按接受率分位定 γ 策略，最后按功率峰值定同时验证数。三者中任何一项被突破，系统都会以尾延迟而非均值吞吐的形式表现出来——因为均值被高接受率请求撑住，尾部被低接受率请求拖垮。规模化的正确做法不是把 γ 调大追求均值加速，而是把 γ 与并发验证数做成受显存、功率、接受率分位三重约束的调度变量。落到具体机制上：调度器在每次组批时读取当前显存余量、功率余量与近期接受率分位，对每个请求解一个小的约束优化，决定其 γ 取值与是否进入投机路径；这个决策的频率应与连续批处理的迭代节奏对齐，而不是按请求静态配置。</p>\n<h3 id=\"alg-speculative-draft-verify-sec-39\">三十九 · 接受率塌陷：从分布失配到负收益</h3>\n<p>低接受率不是“慢一点”，而是把投机解码的收益结构整个翻转。加速比近似为 <span class=\"formula\">$$\\text{加速比}\\approx\\frac{\\mathbb{E}[\\text{接受长度}]+1}{1+c\\gamma}$$</span>，其中 c 是草稿单 token 开销相对目标单 token 开销的比值。当 <span class=\"formula\">$$\\mathbb{E}[\\text{接受长度}]$$</span> 掉到接近 0，分子趋近 1，而分母因 <span class=\"formula\">$$c\\gamma$$</span> 膨胀，加速比小于 1——每生成一个 token 反而比纯目标解码更贵。工程上要盯的不是平均接受率，而是按请求类型切分的接受长度分布：代码补全里的缩进、括号闭合、重复标识符接受率高；agent 循环里的工具调用参数、自由文本推理段接受率低。同一个 γ 在两类流量上表现相反，混合后均值会掩盖塌陷。</p>\n<p>诊断手段是在验证前向里逐位置记录 <span class=\"formula\">$$\\min(1, p_j/q_j)$$</span> 的取值与首次拒绝位置 k。若拒绝集中在前两个位置，说明草稿模型与目标模型在上下文开头就分歧，通常是草稿的 tokenizer 或 prompt 模板与目标不一致；若拒绝均匀散布在 γ 个位置，则是草稿容量不足或量化误差累积。前者改配置，后者降 γ 或换草稿。代价上，逐位置日志本身要落盘 γ 个浮点，高并发小批下写日志的带宽不可忽略，应采样而非全量。</p>\n<p>具体例子：一个 agent 循环里目标模型是代码专用大模型，草稿是通用小模型，工具调用段的 JSON 键名接受率极低，而函数体段接受率高。按请求类型把 γ 从固定值改为分段值——工具段 γ=2、函数体段 γ=8——比全局调参更稳。这是路由问题，不是模型问题。</p>\n\n<h3 id=\"alg-speculative-draft-verify-sec-40\">四十 · 验证前向的 KV 回滚与显存越界</h3>\n<p>验证阶段把 γ 个候选一次性写入 KV cache，接受前缀长度 k 后要把 k 之后的 γ−k 个位置的 KV 丢弃。若实现成“先写满再截断”，分页 KV 块管理里那些块必须被正确释放，否则每轮泄漏 γ−k 个 token 的块。长上下文下这不是小数：γ=8、平均接受 3，每步泄漏 5 个位置的 KV，几千步后块池耗尽，触发 OOM 或被迫驱逐活跃请求的块，尾延迟直接尖刺。</p>\n<p>正确做法是验证前向只分配“临时槽位”，接受判定完成后按 k 提交、按 γ−k 回滚，回滚路径与正常释放路径共用同一套块表引用计数。诊断信号是块池的空闲块数随步数单调下降而活跃请求数不变——这就是泄漏。另一个信号是验证前向的峰值显存：γ 个位置的 logits 与中间激活是瞬时的，但若框架把草稿与目标的 KV 都常驻在同一池里，峰值会叠加草稿模型的权重与它自己的 KV。</p>\n<p>显存账要算清：草稿模型权重 + 草稿 KV + 目标权重 + 目标 KV + 验证临时槽位。前四项挤压并发批大小，第五项挤压峰值余量。低延迟 SLO 下批大小被压到很小，吞吐掉得比延迟收益快，这是“容量受限”的具体形态。工程判断是给验证临时槽位设硬上限，超限就降 γ，而不是让分配器去赌。</p>\n\n<h3 id=\"alg-speculative-draft-verify-sec-41\">四十一 · 批抖动：γ 动态调整与连续批处理的耦合</h3>\n<p>按接受率动态调 γ 是稳定性技巧，但它和连续批处理天然冲突。连续批处理按 token 步推进，一个批里的请求各自有不同的 γ 和不同的已接受前缀长度，验证前向的序列长度参差不齐。若调度器按最长序列对齐，短请求被 padding 拖慢；若按请求分组，批被切碎，算术强度下降，验证前向“把 γ 个位置合并为一次前向”的收益被抵消。</p>\n<p>抖动的来源有三层：γ 随接受率滑动窗口变化导致每步的计算图形状变化；接受长度 k 的方差导致 KV 提交量方差；请求到达的泊松性导致批组成变化。三者叠加，GPU 利用率曲线呈锯齿。诊断看两个量：每步实际参与验证的 token 数与理论最大值的比值，以及批内 γ 的方差。比值低说明 padding 浪费，方差大说明调度器在追着 γ 跑。</p>\n<p>缓解手段是把 γ 的调整放在请求粒度而非步粒度，一个请求在其生命周期内 γ 分段稳定，只在接受率窗口显著偏移时切换；同时把验证前向的批按 γ 分桶，桶内对齐、桶间并行发射。代价是桶间并行需要更多并发流，小 batch 下流切换开销会吃掉收益，因此分桶数要设上限。具体例子：高并发小批的代码补全场景，把 γ 限定在 {2,4,8} 三档，调度器按档位聚合，比连续取值稳定得多。</p>\n\n<h3 id=\"alg-speculative-draft-verify-sec-42\">四十二 · 路由不均与尾延迟尖刺</h3>\n<p>路由不均有两种。第一种是请求到副本的不均：某些副本承载了高接受率的代码补全流量，另一些承载低接受率的 agent 自由文本流量，前者吞吐高、后者排队，全局尾延迟由慢副本决定。第二种是同一副本内草稿与目标的分工不均：草稿模型在低接受率段白跑 γ 步，目标模型在验证时被迫处理长候选，两侧的 SM 占用此消彼长。</p>\n<p>尾延迟尖刺的典型触发是长上下文请求撞上 KV 回滚：一个已积累数万 token 的会话突然进入验证，临时槽位分配触发块池扩容或驱逐，单步时延从毫秒级跳到数十毫秒。监控要按分位数而非均值看每 token 时延，并把尖刺与块池空闲量、γ 值、接受长度 k 三者做关联。若尖刺总在 k 远小于 γ 时出现，说明回滚路径有同步点；若总在块池低位出现，说明容量规划不足。</p>\n<p>路由层可做的判断是按会话历史接受率给请求打标签，把高接受率会话导向 γ 大的副本配置，低接受率会话导向 γ 小、草稿权重更轻的配置。这不是改解码分布，只是资源匹配。代价是标签需要冷启动样本，新会话前若干步按保守 γ 跑，接受率稳定后再升级。</p>\n\n<h3 id=\"alg-speculative-draft-verify-sec-43\">四十三 · 监控指标与回滚开关</h3>\n<p>监控的最小集合是：按请求类型的接受长度分布（均值与 P5）、首次拒绝位置直方图、每步验证 token 填充率、块池空闲块数与泄漏速率、每 token 时延的 P50/P99、草稿与目标各自的 SM 占用。这些量里，接受长度 P5 和填充率是领先指标，尾延迟是滞后指标；前者恶化时后者还没动，此时调 γ 成本最低。</p>\n<p>回滚要分级，不能只有“关掉投机”一个开关。一级回滚是降 γ 到 1，等价于纯目标解码但保留草稿路径，用于验证是 γ 过大而非草稿失配；二级是跳过草稿、直接目标解码，用于草稿模型异常；三级是切回无投机的部署配方，用于 KV 回滚路径出问题。分级的意义在于每一级保留不同的诊断信息，一级回滚后仍能观察草稿的 q 分布，便于定位。</p>\n<p>自动回滚的触发条件要绑定量而非时间：接受长度 P5 连续若干步低于阈值、块池空闲块低于安全水位、每 token 时延 P99 超过 SLO 的倍数。时间窗口触发容易在流量突变时误杀。具体机制上，把 γ 的调整与回滚做成同一个控制回路：控制器的输出是 γ，γ=1 即一级回滚，控制器饱和到下限自然进入回滚态，不需要两套逻辑。</p>\n<p>最后落在工程判断上：投机解码的失败模式几乎都收敛到“接受率与容量的耦合”——接受率低则 γ 该降，但降 γ 又改变批形状引发抖动，抖动推高尾延迟，尾延迟触发扩容又挤压块池。诊断的抓手是首次拒绝位置直方图与块池泄漏速率这两个量，它们分别指向草稿失配与回滚缺陷，而这两条正是本算法在长上下文与低接受率任务上仅有的两个结构性弱点。</p>\n\n\n<h3 id=\"alg-speculative-draft-verify-sec-44\">四十四 · 失效边界：从接受率塌陷到 KV 回滚的工程诊断</h3>\n<p>投机解码的收益完全由接受率决定，而接受率一旦塌陷，系统进入负收益区。用加速比公式定位边界：<div class=\"formula\">$$\\text{加速比}\\approx\\frac{\\mathbb{E}[\\text{接受长度}]+1}{1+c\\gamma}$$</div>其中 c 是草稿单 token 开销与目标验证单 token 开销之比。当任务分布偏移（例如代码补全从模板化补全切到开放式 agent 循环，或工具调用返回结构化 JSON），草稿模型与目标模型的分布分歧变大，E[接受长度] 迅速下降，而分母随 γ 线性增长，加速比跌破 1。诊断信号不是平均接受率，而是按请求类型分桶的接受长度直方图：若某桶的接受长度集中在 1–2 而 γ 仍被全局策略推到 8，该桶就在净亏损。工程动作是分桶维护 γ 的自适应表，按最近窗口的接受率反推最优 γ，使 cγ 与 E[接受长度]+1 同阶；同时给每个桶设加速比下限，跌破即对该桶关闭投机路径、退回普通解码。</p>\n<p>KV 回滚是第二个失效点，且比接受率更隐蔽。验证前向把 γ 个候选位置一次性写入草稿与目标两套 KV 缓存，接受前缀长度 k 后只提交前 k 个 token，剩余 γ−k 个位置的 KV 必须作废。若实现用追加写而不做逻辑截断，长上下文下会出现两套 KV 的长度错位：草稿模型下一轮基于被污染的缓存继续提议，目标模型的注意力窗口混入已丢弃候选的残差，表现为输出质量缓慢劣化而非报错。诊断手段是校验每轮提交后两套 KV 的序列长度与位置编码是否严格一致，并在回滚路径上记录丢弃槽位的复用次数；复用次数异常升高说明截断逻辑在走慢路径。代价上，回滚本身不增加算力，但额外的缓存管理与一致性校验在长上下文下抬高每轮固定开销，压缩了投机带来的时延收益。</p>\n<p>显存与批抖动是第三个失效面。草稿模型与目标模型同驻，权重与两套 KV 同时占用显存，直接挤压并发批大小；在短 prompt、中等生成、高并发小批的代码补全负载下，批大小下降会放大尾延迟尖刺——少数长上下文请求把 KV 撑大后，调度器为腾空间驱逐其他请求的缓存，触发重算，尾延迟从稳定区间跳变。监控应盯三个量：草稿与目标 KV 的显存占比、每批实际并发数与目标并发数的比值、以及 P99 与 P50 每 token 时延的比值。比值持续偏离说明批抖动已成主因，此时应降低 γ 以缩小验证前向的瞬时 KV 峰值，或对长上下文请求单独路由到不启用投机的通道。</p>\n<p>路由不均是分布式部署下的特有失败模式。按请求哈希或轮询把流量分到多个副本时，各副本的接受率因流量构成不同而分化，高接受率副本被持续压满、低接受率副本空转，集群整体加速比被最慢副本拖住。诊断靠按副本采集接受长度与队列深度的联合分布，识别“高接受率但队列长”的副本——它不是容量不足，而是路由把同质请求集中投给了它。修正手段是把接受率作为路由权重的一部分，让草稿-目标配对相近的请求落在同一副本，代价是路由层需要维护轻量的接受率画像并有滞后，画像过期会导致振荡，因此权重更新需带阻尼。回滚策略上，任何一次 γ 调整或路由权重变更都应保留上一版配置的快照，一旦 P99 时延或输出一致性校验失败，按副本粒度回退而非全局回退，避免一次误判拖垮整个集群。</p>\n<h3 id=\"alg-speculative-draft-verify-sec-45\">四十五 · 同族谱系与选型维度</h3>\n<p>投机草稿-并行验证不是孤立算法，它处在一个“用便宜计算换串行步数”的家族里。同族成员至少包括：多解码头投机（在目标模型上挂若干轻量解码头，一次前向出多 token）、特征级投机采样（在隐层特征空间做草稿，绕过词表采样）、投机检索预取（调度层重叠检索与生成，不改解码分布）、目标与草稿联合量化（把草稿与目标一起压到低精度以腾显存）。选型不是挑“最强”，而是挑“在给定 SLO 与显存预算下，谁的边际收益先饱和”。</p>\n<p>四个正交维度决定取舍：其一，草稿来源——独立小模型、附加解码头、检索命中、还是特征外推，直接决定草稿的显存占用与 q 分布质量；其二，分布保真度——是否严格保证输出分布等于目标模型，这决定能否用于工具调用与结构化输出这类正确性敏感路径；其三，验证粒度——一次前向验证 γ 个位置，还是逐位置校验，决定算术强度提升幅度；其四，KV 一致性代价——草稿与目标各自维护 KV 时，回滚与对齐的复杂度随上下文长度增长。任何选型表都必须把“接受率”与“显存挤压”放在同一张纸上权衡，因为二者是同一枚硬币的两面。</p>\n<p>具体机制上，草稿-验证路径的收益由接受长度期望刻画：</p>\n<div class=\"formula\">$$\\mathbb{E}[\\text{接受长度}]=\\sum_{i=1}^{\\gamma}\\prod_{j=1}^{i}\\min\\left(1,\\frac{p_j}{q_j}\\right),\\quad \\text{加速比}\\approx\\frac{\\mathbb{E}[\\text{接受长度}]+1}{1+c\\gamma}$$</div>\n<p>其中 c 是草稿单 token 成本相对目标单 token 成本的比值。这个式子已经说明选型的核心判据：加速比的分母随 γ 线性增长，分子只随接受长度亚线性增长，因此当 c 不够小或接受率不够高时，γ 增大反而拖慢。工程上把它读成一句判断——草稿必须“足够便宜且足够准”，否则并行验证的算术强度红利被草稿开销吃掉。举例：代码补全场景短 prompt、中等生成、高并发小批，草稿若与目标同精度同规模，c 接近 1，加速比上限被压到 2 以下；把草稿换成同族小模型或附加解码头，c 降到可接受区间，γ 才有调整空间。</p>\n\n<h3 id=\"alg-speculative-draft-verify-sec-46\">四十六 · 决策表：五类候选的适用条件</h3>\n<p>下表把同族算法按“草稿来源 / 保真度 / 验证粒度 / 主要代价”四列对齐，供工程侧按负载形态查表。表中不写具体加速数字，只写条件与代价方向。</p>\n<table class=\"mini\"><thead><tr><th>算法</th><th>草稿来源</th><th>分布保真</th><th>验证粒度</th><th>主要代价与适用条件</th></tr></thead><tbody>\n<tr><td>草稿模型 + 并行验证</td><td>独立小模型自回归出 γ 个候选及 q</td><td>严格一致（拒绝采样 + 残差修正）</td><td>一次前向验证 γ 位置</td><td>草稿权重与 KV 额外占显存，挤压并发批；适合内存带宽受限、接受率可测的逐 token 解码</td></tr>\n<tr><td>多解码头投机</td><td>目标模型上挂轻量解码头</td><td>取决于头是否校准，通常需接受准则兜底</td><td>单次前向多位置</td><td>省去独立草稿权重，但头与主干共享显存；适合目标模型结构允许挂头的场合</td></tr>\n<tr><td>特征级投机采样</td><td>隐层特征外推，跳过词表采样</td><td>需额外准则保证，工程复杂度高</td><td>特征空间并行</td><td>草稿极廉价但实现与调试成本高；适合长生成、词表大的场景</td></tr>\n<tr><td>投机检索预取</td><td>检索命中片段作为候选</td><td>不改解码分布，属调度层重叠</td><td>不验证 token，重叠 I/O 与计算</td><td>收益来自隐藏检索延迟，不解决逐 token 串行；适合 RAG 类带外部检索的负载</td></tr>\n<tr><td>目标与草稿联合量化</td><td>草稿与目标同压到低精度</td><td>量化误差需评估，接受率可能下降</td><td>与草稿-验证正交，可叠加</td><td>腾出显存换并发，但低精度下 q 与 p 失配会拉低接受率；适合显存紧、精度容忍度明确的部署</td></tr>\n</tbody></table>\n<p>读表要点：第一行是本条目的主角，它的独特价值是“分布严格不变 + 一次前向验证 γ 位置”这两件事同时成立，因此它是唯一能直接用在工具调用与结构化输出上的候选。第二、三行用“省掉独立草稿”换显存，但保真度需要额外工程兜底。第四行根本不改解码分布，它解决的是另一类延迟（检索 I/O），不要拿它和草稿-验证比加速比。第五行是正交手段，可与第一行叠加，但叠加时要用接受率监控判断量化是否已经把 q 拉偏。</p>\n<p>适用条件的硬边界有三条：草稿显存必须与目标权重及其 KV 同驻而不把并发批压到 SLO 以下；接受率必须可在线测量并反馈到 γ；长上下文下草稿与目标 KV 的一致性维护成本必须可接受。三条中任一不成立，就应退回无投机的连续批处理，或改用调度层手段（如检索预取）而不是解码层投机。</p>\n\n<h3 id=\"alg-speculative-draft-verify-sec-47\">四十七 · 选型伪代码：按接受率与显存余量分流</h3>\n<p>把决策表写成可执行的分流逻辑，比记忆表格更可靠。下面给出思路级伪代码，强调判据顺序：先看显存余量，再看可测接受率，最后看保真度要求。</p>\n<ul>\n<li>若任务要求输出分布严格等于目标模型（工具调用、结构化输出、代码补全的正确性敏感路径），只允许第一行或“第一行 + 联合量化”，且量化后必须复测接受率。</li>\n<li>若显存余量不足以同驻独立草稿，优先考虑多解码头或特征级草稿；若二者工程成熟度不足，退回无投机路径并靠连续批处理保吞吐。</li>\n<li>若瓶颈在检索 I/O 而非逐 token 解码，选投机检索预取，不要在本路径上堆 γ。</li>\n<li>若接受率在线测量低于使加速比大于 1 的阈值，立即下调 γ 直至草稿开销与验证开销比值回到可接受区间；持续低于阈值则关闭投机。</li>\n</ul>\n<p>伪代码的关键是“阈值来自公式而非经验”：由加速比表达式反解，要求 (E[接受长度]+1)/(1+cγ) &gt; 1，即 E[接受长度] &gt; cγ。工程上把 c 用实测草稿单步时延除以目标单步时延估计，把 E[接受长度] 用滑动窗口接受率估计，两者比较即得是否继续投机的判据。这个判据每批都可重算，因此 γ 的调整可以做成批级反馈环，而不是离线调参。</p>\n<p>系统代价要在此处点明：分流逻辑本身几乎不耗算力，但它决定的 γ 直接改变显存与带宽占用。γ 越大，验证前向一次处理的位置越多，算术强度越高、每 token 的内存带宽压力越低，但草稿侧自回归步数也越多，草稿 KV 随之增长。举例：高并发小批的代码补全服务中，若把 γ 从保守值上调，单请求尾延迟可能因草稿串行步数增加而变差，尽管吞吐可能上升；这正是需要用每 token 时延与尾延迟双指标约束 γ 的原因。</p>\n\n<h3 id=\"alg-speculative-draft-verify-sec-48\">四十八 · 与调度层和量化手段的叠加次序</h3>\n<p>选型不只是“选一个”，还包括“按什么次序叠加”。正确的叠加次序是：先定解码层是否投机（第一行与否），再定精度层是否联合量化，最后定调度层是否做检索预取与连续批处理。次序颠倒会污染判据——若先量化再选投机，低精度下 q 与 p 的失配会让接受率测量失真，从而误判草稿模型不合格。</p>\n<p>叠加时的机制冲突要提前识别：联合量化压缩草稿与目标权重腾出显存，理论上允许更大并发批或更大 γ，但低精度会同时改变 p 与 q，接受判定 min(1, p/q) 对二者比值敏感，量化误差不同步时接受率下降。因此叠加后必须重新跑接受率监控，而不是沿用全精度下的 γ。同理，检索预取与草稿-验证分处调度层与解码层，二者可并行存在，但预取占用的带宽与显存会挤压草稿 KV 的空间，容量规划要把两者算进同一本账。</p>\n<p>具体例子：一个 agent 循环负载，每步都要调工具并读回结果，prompt 短、生成中等、并发高。此时逐 token 解码是主瓶颈，草稿-验证是第一选择；若显存吃紧，先上联合量化腾空间，再复测接受率决定 γ；检索预取只在工具返回的大块上下文注入时才有边际价值，不应作为主手段。这个次序保证每一层叠加都有可测的边际收益，而不是把三种手段一起打开后无法归因。</p>\n\n<h3 id=\"alg-speculative-draft-verify-sec-49\">四十九 · 失败模式归因与切换判据</h3>\n<p>选型表的价值在于失败时能快速归因到“选错了”还是“调错了”。三类典型失败：其一，加速比退化甚至负收益——归因于接受率低或 c 偏大，属于选型或 γ 配置问题，判据是 E[接受长度] &gt; cγ 不成立；其二，尾延迟恶化而吞吐尚可——归因于 γ 过大导致草稿串行步数增加，属于参数问题，下调 γ 即可；其三，长上下文下 KV 回滚出错或一致性维护成本陡增——归因于草稿与目标 KV 分离管理的固有代价，属于机制问题，此时应考虑换用共享主干的解码头方案，或缩短投机窗口。</p>\n<p>切换判据要写成可观测的量：接受率滑动均值、草稿与目标单步时延比 c、草稿 KV 占用占总显存比例、每 token 尾延迟分位数。四个量中任一越界即触发切换评估，而不是等到 SLO 违约才反应。工程判断上，草稿-验证的适用边界是内存带宽受限的逐 token 解码场景，规模上限受草稿显存与接受率约束；一旦负载从“逐 token 串行受限”转为“检索 I/O 受限”或“批处理已饱和”，本算法的边际收益就让位给调度层手段。</p>\n<p>最后落在具体机制上：γ 的在线调整应绑定到“草稿开销与验证开销比值接近最优”这一目标，而不是绑定到接受率的绝对值。因为接受率高但 c 也高时，增大 γ 仍可能亏；接受率中等但 c 极低时，增大 γ 仍可能赚。把比值作为控制量，配合每批重算的 E[接受长度] &gt; cγ 判据，才能让选型在负载漂移时保持正确，而不是在离线调参的静态点上失效。</p>\n\n<h3 id=\"alg-speculative-draft-verify-sec-50\">五十 · 同族算法选型：草稿-验证的边界与替代路径</h3>\n<p>把草稿-并行验证放进同族算法谱系里，选型的判据不是\"谁更快\"，而是\"谁在给定接受率下不亏\"。同族的投机检索预取在调度层重叠检索与生成、不改解码分布，属于零风险但收益上限受检索命中率约束的路径；草稿-验证则用廉价模型换并行度，收益完全由接受长度决定。二者的分水岭是：任务是否存在一个与目标模型分布足够接近、且成本远低于目标模型的草稿源。代码补全与 agent 循环里，草稿可由同族小模型或上一轮上下文缓存提供，接受率通常足以覆盖草稿开销；而在开放域长文生成、草稿与目标分布漂移大的场景，检索预取的确定性收益反而更稳。选型时先算一笔账：若草稿单步成本为目标单步的 c 倍、提出 γ 个候选，则加速比近似为 (E[接受长度]+1)/(1+cγ)，其中 E[接受长度]=Σ_{i=1}^{γ}∏_{j=1}^{i}min(1,p_j/q_j)。cγ 一旦逼近甚至超过 E[接受长度]，并行验证就从加速变成拖累。</p>\n<p>决策表按三个可观测维度切分，避免凭感觉调参：</p>\n<table class=\"mini\"><thead><tr><th>条件</th><th>选草稿-验证</th><th>选检索预取/纯自回归</th></tr></thead><tbody><tr><td>草稿源与目标分布接近（同族小模型、缓存前缀）</td><td>是，接受率高，γ 可放大</td><td>否，检索命中率不稳定</td></tr><tr><td>显存余量不足以同驻两份权重及 KV</td><td>否，草稿挤压并发批大小</td><td>是，调度层重叠不占额外权重</td></tr><tr><td>长上下文、KV 回滚频繁</td><td>谨慎，需一致性维护</td><td>是，不改解码分布</td></tr><tr><td>结构化输出/工具调用，正确性敏感</td><td>是，拒绝采样保证分布不变</td><td>可用，但收益有限</td></tr></tbody></table>\n<p>失效条件集中在两处。其一是低接受率：首次拒绝处从残差分布 max(0,p−q) 归一化后采样修正 token 并截断后续候选，被丢弃的候选白付了草稿算力与验证前向的 KV 写入，γ 越大浪费越重，必须按滑动窗口接受率动态收缩 γ，把草稿开销与验证开销的比值压回最优区间。其二是长上下文下的 KV 一致性：接受前缀 k 个 token 一次性提交、解码位置前进 k+1，未接受候选的 KV 必须回滚，草稿与目标两套 KV 在长上下文里维护成本随序列长度上升，容量规划要同时容纳两份权重及其 KV，直接压缩低延迟 SLO 下的并发批大小。工程判断是：先用小 γ 探接受率，接受率稳定高于阈值再放大 γ；若接受率长期低迷，退回检索预取或纯自回归，别用调参掩盖分布漂移。</p>\n<table class=\"mini\" data-fig=\"alg-quick\"><caption>速查：这一页回答的五件事</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>年份 · 方向</td><td>2022 · 代码后训练与数据目标</td></tr><tr><td>解决什么</td><td>代码补全与 agent 循环中自回归解码逐 token 串行，单步受内存带宽限制，GPU 算力闲置，端到端时延难以满足…</td></tr><tr><td>一句话机制</td><td>用廉价草稿模型一次提出 γ 个候选 token，目标模型一次前向并行打分，按拒绝采样接受最长一致前缀，保证输出分布不变。</td></tr><tr><td>代价与失效</td><td>草稿模型额外占用显存与算力，低接受率时加速比退化甚至负收益，需按任务动态调 γ。；验证前向的 KV 写入与回滚需要额外缓存管理，长上下文下…</td></tr><tr><td>后继</td><td>文法约束解码</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：algorithms/alg-speculative-draft-verify · 共 8 个片段</p>\n";break;}}})();
